--
-- Table structure for table `admin_panel_csropportunity`
--

DROP TABLE IF EXISTS `admin_panel_csropportunity`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_panel_csropportunity` (
  `opp_id` int NOT NULL AUTO_INCREMENT,
  `title` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `opportunity_type` longtext COLLATE utf8mb4_unicode_ci,
  `category` longtext COLLATE utf8mb4_unicode_ci,
  `submission_deadline` longtext COLLATE utf8mb4_unicode_ci,
  `portal_url` longtext COLLATE utf8mb4_unicode_ci,
  `requirements` longtext COLLATE utf8mb4_unicode_ci,
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidence` double NOT NULL,
  `link_status` longtext COLLATE utf8mb4_unicode_ci,
  `link_verified_at` longtext COLLATE utf8mb4_unicode_ci,
  `fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `canonical_url` longtext COLLATE utf8mb4_unicode_ci,
  `content_hash` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evidence_locator` longtext COLLATE utf8mb4_unicode_ci,
  `evidence_text` longtext COLLATE utf8mb4_unicode_ci,
  `extraction_method` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `first_seen_at` datetime(6) DEFAULT NULL,
  `http_status` int DEFAULT NULL,
  `last_seen_at` datetime(6) DEFAULT NULL,
  `parser_version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `redirect_chain` longtext COLLATE utf8mb4_unicode_ci,
  `retrieved_at` datetime(6) DEFAULT NULL,
  `source_domain` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_snapshot` longtext COLLATE utf8mb4_unicode_ci,
  `source_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_url` longtext COLLATE utf8mb4_unicode_ci,
  `verification_reason` longtext COLLATE utf8mb4_unicode_ci,
  `verification_status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_seen_live_at` datetime(6) DEFAULT NULL,
  `raw_metadata` json NOT NULL DEFAULT (_utf8mb4'{}'),
  PRIMARY KEY (`opp_id`),
