{}'),(632,'CSR Initiative: Environment & Sustainability Initiative','CSR Project Partnership','Environment & Sustainability',NULL,'https://www.cummins.com/en-in/en/in/company/corporate-responsibility#:~:text=-%20Practice%20highest%20standards%20of%20corporate%20citizenship','Schedule VII CSR collaboration under Environment & Sustainability.','INVALID_SYNTHETIC',1,'LINK_OK',NULL,'a1ed0c7466a1da4bc6e71792166601bc','COMP_TOP200_048',NULL,'1a236a3a9fbafda0dd0159da23f28948',NULL,'- Practice highest standards of corporate citizenship by always acting ethically and with integrity, while pursuing and applying \'best practices\' to create a cleaner, safer and healthier environment',NULL,'2026-10-19 12:17:48.305988',NULL,'2026-10-19 12:17:48.305988',NULL,NULL,'2026-10-19 12:17:48.305988',NULL,NULL,NULL,'https://www.cummins.com/en-in/en/in/company/corporate-responsibility#:~:text=-%20Practice%20highest%20standards%20of%20corporate%20citizenship',NULL,'SOURCE_CONFIRMED','2026-10-19 12:17:48.305988','{}'),(633,'CSR Initiative: Cummins continues to extend environmental initiatives across the company’s supply chain','CSR Project Partnership','Environment & Sustainability',NULL,'https://www.cummins.com/en-in/company/esg/sustainability-progress-reports#:~:text=Cummins%20continues%20to%20extend%20environmental%20initiatives%20across','Schedule VII CSR collaboration under Environment & Sustainability.','INVALID_SYNTHETIC',1,'LINK_OK',NULL,'8bb0faf68df002461d26092a31920059','COMP_TOP200_048',NULL,'af94326327e50bcf0d612ba4d072be96',NULL,'Cummins continues to extend environmental initiatives across the company’s supply chain.',NULL,'2026-10-19 12:17:48.305988',NULL,'2026-10-19 12:17:48.305988',NULL,NULL,'2026-10-19 12:17:48.305988',NULL,NULL,NULL,'https://www.cummins.com/en-in/company/esg/sustainability-progress-reports#:~:text=Cummins%20continues%20to%20extend%20environmental%20initiatives%20across',NULL,'SOURCE_CONFIRMED','2026-10-19 12:17:48.305988','{}'),(634,'CSR Initiative: Cummins