INSERT INTO `admin_panel_csrproject` VALUES (2775,'Bosch India has a CSR Committee at the board level which oversees implementation of CSR','Schedule VII Statutory CSR','Bosch India has a CSR Committee at the board level which oversees implementation of CSR. The Bosch Limited CSR Steering Committee comprising of senior leadership of Bosch reports to the Board CSR Committee. The long-term vision and thematic areas have been identified by these Committees, which also facilitate the provision of appropriate budget support for consolidated social engagement. The Committee guides on improving projects and programs, the sustainability and scalability of interventions and creating synergy to build stronger and enhanced engagement with society. The Committee also encourages active involvement through volunteering by Boschlers to actualize the higher vision of social action on the ground.',NULL,NULL,'Verified on Official Portal','https://www.bosch.in/our-company/our-responsibility/corporate-social-responsibility/index-2.html#:~:text=Bosch%20India%20has%20a%20CSR%20Committee%20at',NULL,'2026-10-19T12:16:12.064937+00:00',0,'LINK_OK',NULL,'8d8cff5c64fbd93cefb2c1a980036748','COMP_TOP200_064',NULL,'4c894f912b067a2132030a067c85379a',NULL,'Bosch India has a CSR Committee at the board level which oversees implementation of CSR. The Bosch Limited CSR Steering Committee comprising of senior leadership of Bosch reports to the Board CSR Committee. The long-term vision and thematic areas have been identified by these Committees, which also facilitate the provision of appropriate budget support for consolidated social engagement. The Committee guides on improving projects and programs, the sustainability and scalability of interventions and creating synergy to build stronger and enhanced engagement with society. The Committee also encourages active involvement through volunteering by Boschlers to actualize the higher vision of social action on the ground.',NULL,'2026-10-19 12:16:12.064937