INSERT INTO `admin_panel_csrproject` VALUES (3281,'We believe in the saying “Give a man a fish and you feed him for a day, but teach a man to','Education & Skill Development','We believe in the saying “Give a man a fish and you feed him for a day, but teach a man to fish and you feed him for a lifetime”; Education enables people to build better lives for themselves and their families, and improves the quality of life for the present and future generations of our country. We organise skill development and income-generating programmes for local communities.',NULL,NULL,'Verified on Official Portal','https://3bblackbio.com/corporate-social-responsibility#:~:text=We%20believe%20in%20the%20saying%20%E2%80%9CGive%20a',NULL,'2026-10-19T12:08:11.600786+00:00',0,'LINK_OK',NULL,'9bde133cc6e7ddd048cc767bb9a532c8','COMP_TOP200_157',NULL,'df74a68eadca9f3d39719cc7eb1e186d',NULL,'We believe in the saying “Give a man a fish and you feed him for a day, but teach a man to fish and you feed him for a lifetime”; Education enables people to build better lives for themselves and their families, and improves the quality of life for the present and future generations of our country. We organise skill development and income-generating programmes for local communities.',NULL,'2026-10-19 12:08:11.600786',NULL,'2026-10-19 12:08:11.600786',NULL,NULL,'2026-10-19 12:08:11.600786',NULL,NULL,NULL,NULL,'SOURCE_CONFIRMED','2026-10-19 12:08:11.600786','{\"title\": \"We believe in the saying “Give a man a fish and you feed him for a day, but teach a man to\", \"summary\": \"We believe in the saying “Give a man a fish and you feed him for a day, but teach a man to fish and you feed him for a lifetime”; Education enables people to build better lives for themselves and their families, and improves the quality of life for the present and future generations of our country. We organise skill development and income-generating programmes for local communities.\", \"focus_area\": \"Education & Skill Development\", \"source_url\": \"https://3bblackbio.com/corporate-social-responsibility#:~:text=We%20believe%20in%20the%20saying%20%E2%80%9CGive%20a\", \"budget_allocated\": \"Verified on Official Portal\", \"verification_status\": \"PUBLISHED\"}',NULL,'ACTIVE','{\"raw_category\": \"category\", \"raw_budget_text\": \"budget\", \"raw_project_name\": \"project_name\"}',NULL,'{}',NULL,'Verified on Official Portal','Education & Skill Development',NULL,'We believe in the saying “Give a man a fish and you feed him for a day, but teach a man to'),(3282,'Our education and employment initiatives are implemented directly or through collaboration','Education & Skill Development','Our education and employment initiatives are implemented directly or through collaboration with communities and NGOs, etc. The Company’s aim is to provide education to the underprivileged children and students by providing merit based scholarships. Assistance is given to such communities by helping them develop technical skills to enhance livelihood/employability.',NULL,NULL,'Verified on Official Portal','https://3bblackbio.com/corporate-social-responsibility#:~:text=Our%20education%20and%20employment%20initiatives%20are%20implemented',NULL,'2026-10-19T12:08:11.600786+00:00',0,'LINK_OK',NULL,'9f61fb99587c52ffe3ba90aa25beff33','COMP_TOP200_157',NULL,'bcddc723000f9f2edbcfe4cd2e10bdec',NULL,'Our education and employment initiatives are implemented directly or through collaboration with communities and NGOs, etc. The Company’s aim is to provide education to the underprivileged children and students by providing merit based scholarships. Assistance is given to such communities by helping them develop technical skills to enhance livelihood/employability.',NULL,'2026-10-19 12:08:11.600786',NULL,'2026-10-19 12:08:11.600786',NULL,NULL,'2026-10-19 12:08:11.600786',NULL,NULL,NULL,NULL,'SOURCE_CONFIRMED','2026-10-19 12:08:11.600786','{\"title\": \"Our education and employment initiatives are implemented directly or through collaboration\", \"summary\": \"Our education and employment initiatives are implemented directly or through collaboration with communities and NGOs, etc. The Company’s aim is to provide education to the underprivileged children and students by providing merit based scholarships. Assistance is given to such communities by helping them develop technical skills to enhance livelihood/employability.\", \"focus_area\": \"Education & Skill Development\", \"source_url\": \"https://3bblackbio.com/corporate-social-responsibility#:~:text=Our%20education%20and%20employment%20initiatives%20are%20implemented\", \"budget_allocated\": \"Verified on Official Portal\", \"verification_status\": \"PUBLISHED\"}',NULL,'ACTIVE','{\"raw_category\": \"category\", \"raw_budget_text\": \"budget\", \"raw_project_name\": \"project_name\"}',NULL,'{}',NULL,'Verified on Official Portal','Education & Skill Development',NULL,'Our education and employment initiatives are implemented directly or through collaboration'),(3283,'We believe in customizing the implementation of CSR activities as per the need of the soci','Healthcare & Nutrition','We believe in customizing the implementation of CSR activities as per the need of the society and a call from nearby communities. Company found some basic needs of the society in nearby connecting villages and decided to fulfill it by providing the supply of food and necessary items during the COVID-19 Pandemic to the people in need. We also provided healthcare and hygiene supplies to fight the pandemic. The company also contributes to provide relief to the disaster-stricken communities and regions during the times of floods, cyclones, earthquakes and other such natural calamities.',NULL,NULL,'Verified on Official Portal','https://3bblackbio.com/corporate-social-responsibility#:~:text=We%20believe%20in%20customizing%20the%20implementation%20of',NULL,'2026-10-19T12:08:11.600786+00:00',0,'LINK_OK',NULL,'bb46cde94a307330d84693ff55d1c70c','COMP_TOP200_157',NULL,'67dd8