INSERT INTO `admin_panel_job` VALUES (4922,'JOB_3817e0a3','Analyst, Banking Alliances','Banking',NULL,'Lucknow',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-07T02:07:28-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740730005','https://razorpay.com/careers/','2026-10-07T15:54:44.280386+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','7ae74a39372e7d519344318c3f75a43c1019f699c5cb2b437f8c8f42_4922','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740730005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740730005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4457906005, \"location\": {\"name\": \"Lucknow\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Lucknow\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4740730005, \"updated_at\": \"2026-10-07T02:07:28-04:00\", \"requisition_id\": \"14798\", \"title\": \"Analyst, Banking Alliances\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-10-07T01:44:37-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the Role: &lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;We are looking for a driven and knowledgeable Sales Manager to lead Payment Gateway (PG) business growth across strategic high-potential locations. The ideal candidate will have a strong grasp of the payments ecosystem, hands-on experience working with banks and financial institutions, and the ability to build and leverage government relationships to drive adoption and revenue. &lt;br&gt;&lt;br&gt;&lt;strong&gt;Key Responsibilities&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Payment Gateway Sales &amp;amp; Business Development &lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;\\u2022&amp;nbsp; Own end-to-end sales of PG solutions to merchants, enterprises, and institutions in the assigned strategic location &lt;br&gt;\\u2022&amp;nbsp; Identify, prospect, and close high-value merchants across sectors such as retail, education, healthcare, and government &lt;br&gt;\\u2022&amp;nbsp; Drive acquisition of new accounts while growing revenue from existing merchant partnerships \\u2022&amp;nbsp; Pitch and position PG products including payment links, UPI, cards, EMI, and BNPL solutions based on merchant needs&lt;br&gt;&lt;br&gt;&lt;strong&gt; Bank &amp;amp; Financial Institution Management &lt;/strong&gt;&lt;br&gt;\\u2022&amp;nbsp; Build and maintain strong relationships with regional and cooperative banks, NBFCs, and nodal banking partners &lt;br&gt;\\u2022&amp;nbsp; Lead commercial negotiations including MDR, settlement cycles, credit limits, and partnership terms&lt;br&gt;\\u2022&amp;nbsp; Coordinate with bank partners for faster onboarding, issue resolution, and co-selling opportunities &lt;br&gt;\\u2022&amp;nbsp; Stay updated on RBI guidelines, banking circulars, and compliance requirements affecting PG operations&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;br&gt;&lt;strong&gt;Government &amp;amp; Institutional Relationships &lt;/strong&gt;&lt;br&gt;\\u2022&amp;nbsp; Develop and manage relationships with state and local government bodies, PSUs, and municipalities for PG adoption in public services &lt;br&gt;\\u2022&amp;nbsp; Identify and pursue opportunities in government collections \\u2014 utility payments, tax portals, welfare disbursements, and e-governance projects &lt;br&gt;\\u2022&amp;nbsp; Represent the company in government tenders, RFPs, and empanelment processes &lt;br&gt;\\u2022&amp;nbsp; Liaise with government officials and decision-makers to position the company as a preferred payments partner&lt;/p&gt;\\n&lt;p&gt;&lt;br&gt;&lt;strong&gt;Commercial Negotiation &amp;amp; Deal Structuring &lt;/strong&gt;&lt;br&gt;\\u2022&amp;nbsp; Lead pricing discussions and commercial structuring for large and strategic deals &lt;br&gt;\\u2022&amp;nbsp; Collaborate with internal product, risk, and finance teams to create customized proposals &lt;br&gt;\\u2022&amp;nbsp; Ensure deal profitability while maintaining competitive positioning in the market &lt;br&gt;&lt;br&gt;&lt;strong&gt;Market Intelligence &amp;amp; Reporting &lt;/strong&gt;&lt;br&gt;\\u2022&amp;nbsp; Track competitor activity, pricing trends, and emerging merchant needs across assigned strategic locations &lt;br&gt;\\u2022&amp;nbsp; Provide regular pipeline reports, forecasts, and market insights to regional leadership &lt;br&gt;\\u2022&amp;nbsp; Represent ground-level feedback to product teams for localization and feature improvements&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;What We&#39;re Looking For Must-Have &lt;/strong&gt;&lt;br&gt;&lt;br&gt;&lt;strong&gt;Skills &amp;amp; Experience &lt;/strong&gt;&lt;br&gt;\\u2022&amp;nbsp; 4\\u20138 years of experience in Payment Gateway, Fintech, or Banking sales &lt;br&gt;\\u2022&amp;nbsp; Deep understanding of PG infrastructure \\u2014 acquiring banks, payment networks, settlement flows, risk &amp;amp; compliance &lt;br&gt;\\u2022&amp;nbsp; Proven track record of commercial negotiation with banks or financial institutions &lt;br&gt;\\u2022&amp;nbsp; Experience managing or engaging with government bodies or PSUs for payments/fintech solutions &lt;br&gt;\\u2022&amp;nbsp; Strong hunter mentality with a consultative sales approach &lt;br&gt;\\u2022&amp;nbsp; Excellent communication, relationship management, and stakeholder influence skills &lt;br&gt;&lt;br&gt;&lt;strong&gt;Good to Have&lt;/strong&gt;&lt;br&gt;\\u2022&amp;nbsp; Prior experience working in or extensively covering the assigned strategic location &lt;br&gt;\\u2022&amp;nbsp; Existing network of merchants, bank officials, or government contacts in Chandigarh, Lucknow, Chennai, Hyderabad, or Kolkata &lt;br&gt;\\u2022&amp;nbsp; Familiarity with RBI payment regulations, PCI-DSS, and digital payment policies &lt;br&gt;\\u2022&amp;nbsp; Understanding of GST, e-invoicing, or government payment use cases&lt;br&gt;&lt;br&gt;&lt;strong&gt;Location: Lucknow&lt;/strong&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4021993005, \"name\": \"Banking\", \"child_ids\": [4147065005, 4021994005, 4021995005, 4021996005, 4021997005, 4021998005], \"parent_id\": 4021992005}], \"offices\": [{\"id\": 4009555005, \"name\": \"Payments\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.280386',NULL,'2026-10-07 15:54:44.280386',NULL,NULL,'2026-10-07 15:54:44.280386',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https://razorpay.com/careers/\"><meta name=\"description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engineering, product, design, marketing &amp; more for freshers and experienced professionals.\">\r\n    <meta name=\"framer-search-index\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-4DmOEMu4PQhg.json\">\r\n    <meta name=\"framer-search-index-fallback\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-aFxS1y2nLCaA.json\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: light)\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: dark)\">\r\n    <!-- Open Graph -->\r\n    <meta property=\"og:type\" content=\"website\">\r\n    <meta property=\"og:title\" content=\"Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay\">\r\n    <meta property=\"og:description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engineering, product, design, marketing &amp; more for freshers and experienced professionals.\