,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Mid Market Sales',NULL,'Bengaluru','Associate Manager, Mid Market Sales'),(4925,'JOB_845a6e4d','Associate Manager, Partnerships ','Partnerships.',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-07T04:58:54-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4737935005','https://razorpay.com/careers/','2026-10-07T15:54:44.370356+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','1ce810302a4b97649761d1abda852163a8ea8fea4466a170954c5da0_4925','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4737935005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4737935005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4456443005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Bengaluru\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4737935005, \"updated_at\": \"2026-10-07T04:58:54-04:00\", \"requisition_id\": \"14762\", \"title\": \"Associate Manager, Partnerships \", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-10-07T04:58:54-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;About the Role : Razorpay\\u2019s partnership team is responsible for seeking and exploring new opportunities with Channel partners. Equipped with your business acumen and extensive product knowledge, you will be on the front line of interacting with our key Technology partners, and helping them find ways to grow using Razorpay&#39;s newest product offerings. Your knowledge of relevant verticals and relationships with key industry players will help grow the enterprise business. As an Associate Manager for Partnership, you will foster and manage relationships with some of the biggest tech companies in India. You will own C-level relationships with key partners and grow them to their potential. You will work on cutting edge payments products that deliver processing solutions for our merchants. You will also create large, consistent business growth streams for Razorpay by unlocking great value for merchants.&lt;/p&gt;\\n&lt;p&gt;As an Associate Manager for Partnership, you will foster and manage relationships with some of the biggest tech companies in India. You will own C-level relationships with key partners and grow them to their potential. You will work on cutting edge payments products that deliver processing solutions for our merchants. You will also create large, consistent business growth streams for Razorpay by unlocking great value for merchants.&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Roles and Responsibilities:&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Account Planning and Execution: Develop account plans for assigned partner portfolio, outlining objectives, strategies, and tactics to drive retention and growth. Execute account plans effectively, ensuring alignment with partner goals and company objectives&lt;/li&gt;\\n&lt;li&gt;Retention Strategy Development: Develop and execute strategies to retain and grow the assigned portfolio. This involves analyzing partner needs, identifying retention risks, and implementing targeted initiatives to mitigate churn&lt;/li&gt;\\n&lt;li&gt;Partner training and education&lt;/li&gt;\\n&lt;li&gt;Partner Performance Monitoring and Reporting&lt;/li&gt;\\n&lt;li&gt;Develop an in-depth knowledge of Razorpay core products via successful completion of required sales Training program, and utilize this knowledge to successfully lead the assigned retention/farming portfolio&lt;/li&gt;\\n&lt;li&gt;Relationship Management- Representing Razorpay at conferences and networking events&lt;/li&gt;\\n&lt;li&gt;Local and Domestic travel might be required on a need basis&lt;/li&gt;\\n&lt;li&gt;Work effectively with internal support departments (Sales, Marketing and Product Development) to develop effective sales strategies that promote sales to new and existing customers \\u25cf Continuously research and remain knowledgeable of industry trends and competition.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;strong&gt;Mandatory Qualification:&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Experience of 2-5 years in sales roles preferably within the payments industry and worked as an individual contributor&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Proven sales experience in specified territories and verticals&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Able to drive customer centricity&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Quick learner, adaptable to changing business needs&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;The role involves domestic traveling and hence candidates need to be prepared for the same&lt;/li&gt;\\n&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4145109005, \"name\": \"Partnerships.\", \"child_ids\": [], \"parent_id\": 4145107005}], \"offices\": [{\"id\": 4009555005, \"name\": \"Payments\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.370356',NULL,'2026-10-07 15:54:44.370356',NULL,NULL,'2026-10-07 15:54:44.370356',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https://razorpay.com/careers/\"><meta name=\"description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engineering, product, design, marketing &amp; more for freshers and experienced professionals.\">\r\n    <meta name=\"framer-search-index\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-4DmOEMu4PQhg.json\">\r\n    <meta name=\"framer-search-index-fallback\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-aFxS1y2nLCaA.json\">\r\n    <link href=\"