FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4739578005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Backend',NULL,'Bengaluru','Engineering Manager'),(4929,'JOB_c10eaa25','Forward Deployed Engineer','Solutions',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-06T06:25:00-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4739199005','https://razorpay.com/careers/','2026-10-07T15:54:44.461096+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','61f1dc9c8b21ebcd44ee19bacdd8e31f0cc5202f2731d7d2b307545c26c92ec5','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4739199005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4739199005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4457095005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Bengaluru\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4739199005, \"updated_at\": \"2026-10-06T06:25:00-04:00\", \"requisition_id\": \"14779\", \"title\": \"Forward Deployed Engineer\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-10-01T01:26:52-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;h1&gt;&lt;strong&gt;Forward-Deployed Engineer, Agent Studio&lt;/strong&gt;&lt;/h1&gt;\\n&lt;h2&gt;&lt;strong&gt;About Agent Studio&lt;/strong&gt;&lt;/h2&gt;\\n&lt;p&gt;Agent Studio helps Razorpay merchants run AI agents across payments, checkout, disputes, subscriptions, reconciliation, risk, and customer workflows. We take the messy, undocumented work merchants do every day and turn it into reliable production agents.&lt;/p&gt;\\n&lt;h2&gt;&lt;strong&gt;The role&lt;/strong&gt;&lt;/h2&gt;\\n&lt;p&gt;We&#39;re hiring a &lt;strong&gt;Forward-Deployed Engineer&lt;/strong&gt; who is equal parts engineer, solution consultant, and merchant partner \\u2014 the single technical owner of the merchant relationship. You&#39;ll sit directly with strategic merchants, run the discovery, find the real constraint behind the ask, design the solution, build the first working version, prove whether it moved the metric, and expand from there.&lt;/p&gt;\\n&lt;p&gt;This is a &lt;strong&gt;deeply customer-facing role.&lt;/strong&gt; You&#39;ll own the conversation \\u2014 not hand it off. You&#39;ll walk into a room where the business owner, the ops lead, and the dashboard all tell different stories, and you&#39;ll be the one who reconciles them into a spec everyone agrees to ship. Then you&#39;ll go build it. You earn the customer&#39;s trust because you can do both \\u2014 reshape the ask &lt;em&gt;and&lt;/em&gt; write the code.&lt;/p&gt;\\n&lt;p&gt;If you like being close to the problem, comfortable in front of customers, &lt;em&gt;and&lt;/em&gt; can ship, this is for you.&lt;/p&gt;\\n&lt;h2&gt;&lt;strong&gt;What you&#39;ll own&lt;/strong&gt;&lt;/h2&gt;\\n&lt;p&gt;&lt;strong&gt;Customer discovery &amp;amp; the relationship&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Own merchant conversations end-to-end \\u2014 discovery calls, workshops, solution reviews, and rollout check-ins. You&#39;re the merchant&#39;s trusted technical advisor.&lt;/li&gt;\\n&lt;li&gt;Sit inside merchant workflows long enough to understand the real process, not the documented one. Ask who actually does the work and what happens when it fails.&lt;/li&gt;\\n&lt;li&gt;Reconcile conflicting signals across business owners, operators, dashboards, CRM, and ticket queues into a clear problem statement.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;strong&gt;Solution design &amp;amp; consulting&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Name the business constraint behind the ask: checkout recovery, dispute win rate, RTO loss, SIP recovery, settlement delay, refund spikes, support load, or cashflow leakage.&lt;/li&gt;\\n&lt;li&gt;Convert fuzzy merchant problems into crisp agent specs: success metric, data sources, tool calls, guardrails, human-in-the-loop points, and rollout plan.&lt;/li&gt;\\n&lt;li&gt;Decide what the agent does on its own, what it recommends, and where a human must approve.&lt;/li&gt;\\n&lt;li&gt;Write the spec clearly enough that product, engineering, legal, and the merchant all agree on what ships.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;strong&gt;Hands-on build &amp;amp; integration&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Build prototypes, connectors, MCP tool specs, eval fixtures, dashboards, and the glue code that gets an agent into production.&lt;/li&gt;\\n&lt;li&gt;Debug integration failures across Razorpay systems, merchant systems, external tools, and model behavior.&lt;/li&gt;\\n&lt;li&gt;Deploy across the constraints that real merchants have \\u2014 auth, networking, data access, latency, cost per run, observability, and compliance \\u2014 and keep them in the design from day one.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;strong&gt;Proof, expansion &amp;amp; productization&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Set quality gates and outcome metrics &lt;em&gt;before&lt;/em&gt; rollout. Track production outcomes, not demo applause.&lt;/li&gt;\\n&lt;li&gt;Measure whether the agent moved the target metric. If it didn&#39;t, diagnose and fix \\u2014 or kill it with evidence.&lt;/li&gt;\\n&lt;li&gt;Drive expansion through building: spot the next high-value use case, prototype it, and deepen the merchant&#39;s agent footprint over time.&lt;/li&gt;\\n&lt;li&gt;Turn repeated field patterns into reusable Agent Studio capabilities \\u2014 connectors, templates, eval packs, docs, platform requirements. You are the field voice that shapes what the platform builds next.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h2&gt;&lt;strong&gt;You may be a fit if you&lt;/strong&gt;&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Have 3+ years shipping production software, and are strong in Python or TypeScript.&lt;/li&gt;\\n&lt;li&gt;Have worked directly with customers, enterprise stakeholders, or operators \\u2014 and are comfortable owning the room and the technical relationship.&lt;/li&gt;\\n&lt;li&gt;Have hands-on experience with APIs, webhooks, auth, data pipelines, and production debugging.&lt;/li&gt;\\n&lt;li&gt;Have practical LLM/agent experience: prompts, tool calling, RAG, evals, or workflow automation.&lt;/li&gt;\\n&lt;li&gt;Prefer ambiguous, high-context problems over clean tickets.&lt;/li&gt;\\n&lt;li&gt;Take ambiguous problems, define the structure, and drive them to resolution&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Write clearly \\u2014 specs, implementation plans, and crisp follow-ups.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h2&gt;&lt;strong&gt;Strong pluses&lt;/strong&gt;&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Prior shape: solutions engineer, solution consultant, sales engineer, founding engineer, product engineer, applied AI engineer, or an operator who wrote code.&lt;/li&gt;\\n&lt;li&gt;Payments, fintech, ecommerce, subscriptions, risk, reconciliation, settlement, or finance-ops experience.&lt;/li&gt;\\n&lt;li&gt;Worked with MCP servers, agent skills, multi-agent workflows, eval harnesses, or LLM observability.&lt;/li&gt;\\n&lt;li&gt;Enterprise integration experience: private connectors, VPC/on-prem constraints, SOC2/ISO reviews.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h2&gt;&lt;strong&gt;What this role is not&lt;/strong&gt;&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Not a pre-sales demo role where success is a slick walkthrough.&lt;/li&gt;\\n&lt;li&gt;Not a pure implementation role where success is shipping whatever the merchant asked for.&lt;/li&gt;\\n&lt;li&gt;Not a support role where success is closing tickets.&lt;/li&gt;\\n&lt;li&gt;Not a research role where success is a clever agent that never reaches production.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4040798005, \"name\": \"Solutions\", \"child_ids\": [], \"parent_id\": 4021999005}], \"offices\": [{\"id\": 4009555005, \"name\": \"Payments\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.461096',NULL,'2026-10-07 15:54:44.461096',NULL,NULL,'2026-10-07 15:54:44.461096',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https://razorpay.com/careers/\"><meta name=\"description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engineering, product, design, marketing &amp; more for freshers and experienced professionals.\">\r\n    <meta name=\"framer-search-index\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-4DmOEMu4PQhg.json\">\r\n    <meta name=\"framer-search-index-fallback\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-aFxS1y2nLCaA.json\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: light)\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: dark)\">\r\n    <!--