raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4739199005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Solutions',NULL,'Bengaluru','Forward Deployed Engineer'),(4930,'JOB_cf8f5f82','Group Manager, Banking Alliance','Banking Alliance',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-07T04:10:37-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740737005','https://razorpay.com/careers/','2026-10-07T15:54:44.487305+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','ef1026a11cfba0543f90f26d98e731c8a1bd2b8a18ede3b27108e0e4_4930','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740737005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740737005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4457912005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Mumbai\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Mumbai\", \"value_type\": \"single_select\"}], \"id\": 4740737005, \"updated_at\": \"2026-10-07T04:10:37-04:00\", \"requisition_id\": \"14799\", \"title\": \"Group Manager, Banking Alliance\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-10-07T04:10:37-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;\\n&lt;div&gt;\\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;The Roles and Responsibilities:&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Own and manage end-to-end strategic bank partnerships, driving long-term value and alignment.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Drive revenue growth by enabling and scaling sales through bank channels.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Lead the end-to-end rollout of banking programs, ensuring seamless execution and adoption.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Position Razorpay POS as the preferred partner for banks\\u2019 merchant acquiring business.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Build and nurture strong, multi-level stakeholder relationships, particularly with product, business, and decision-making teams within partner banks.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Lead RFP preparation, submission, and end-to-end coordination with internal and external stakeholders.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Drive cross-functional collaboration across internal teams to deliver on partner objectives.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Travel regularly to engage with bank and NBFC partners and strengthen on-ground relationships.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: arial, sans-serif;&quot;&gt;Mandatory Requirements:&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;10\\u201312 years of experience, preferably in a bank\\u2019s merchant acquiring or payments business.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Proven experience in banking partnerships, alliances, or channel sales.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Experience in RFP preparation is an added advantage.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Ability to influence senior stakeholders and drive alignment across cross-functional teams.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;AI &amp;amp; Digital Competency :&amp;nbsp;Practical experience using LLMs like ChatGPT or Claude.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Process Automation :&amp;nbsp;Ability to identify manual bottlenecks and apply AI or automation tools to improve efficiency, scale operations, and speed up go-to-market&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, sans-serif; font-size: 12pt;&quot;&gt;Familiarity with AI tools and the ability to leverage them to improve partner engagement, enhance outcomes, and drive overall quality and efficiency.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;/div&gt;\\n&lt;/div&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4135163005, \"name\": \"Banking Alliance\", \"child_ids\": [], \"parent_id\": 4135162005}], \"offices\": [{\"id\": 4024237005, \"name\": \"Razorpay POS\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.487305',NULL,'2026-10-07 15:54:44.487305',NULL,NULL,'2026-10-07 15:54:44.487305',NULL,'<!doctype html>\r\n<!-