.woff2) format(\'woff2\');\r\n  unicode-range: U+0460-052F, U+1C80-1C8A, U+20B4, U+2DE0-2DFF, U+A640-A69F, U+FE2E-FE2F;\r\n}\r\n/* cyrillic */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR795U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;\r\n}\r\n/* greek-ext */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79xU6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+1F00-1FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4740737005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Banking Alliance',NULL,'Bengaluru','Group Manager, Banking Alliance'),(4931,'JOB_45bf2e97','Group Manager, Banking Solutions','Banking Solutions',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-29T04:26:31-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4738319005','https://razorpay.com/careers/','2026-10-07T15:54:44.506559+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','488383bd165c694c60eed342f74b4737df1aebce6b9775a9e892e406_4931','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4738319005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4738319005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4456654005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Mumbai\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Mumbai\", \"value_type\": \"single_select\"}], \"id\": 4738319005, \"updated_at\": \"2026-09-29T04:26:31-04:00\", \"requisition_id\": \"14770\", \"title\": \"Group Manager, Banking Solutions\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-09-29T04:26:31-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;&lt;strong&gt;About Razorpay&lt;br&gt;&lt;/strong&gt;&lt;br&gt;Razorpay is a leading full-stack financial services organization building a new-age digital banking hub (Neobank) for businesses. Founded in 2014 by Harshil Mathur and Shashank Kumar, Razorpay processes multi-billion-dollar payment volumes annually across India and international markets, touching over 200 million end-customers through industry leaders such as Airtel, Goibibo, Yatra, Ola, Swiggy, Zomato, and Cred.&lt;br&gt;The company has raised over $700 million in funding from marquee investors including GIC, Sequoia Capital, Tiger Global, Ribbit Capital, and Matrix Partners. Razorpay&#39;s suite of digital offerings spans Payment Gateway, RazorpayX (Business Banking), Razorpay Capital (MSME Lending), Payment Links, Payment Pages, Subscriptions, Smart Collect, Route, Payroll, and Razorpay POS.&lt;br&gt;About Razorpay POS&lt;br&gt;Razorpay POS is Razorpay\\u2019s comprehensive suite of point-of-sale payment solutions, enabling businesses to accept seamless payments across all customer touchpoints\\u2014over the counter, on delivery, or via kiosks and vending machines. Powering over 600,000+ touchpoints across India &amp;amp; the UAE, Razorpay POS (formerly Ezetap, acquired in August 2022) delivers high transaction success rates, real-time transaction analytics via the merchant portal, and flexible in-store EMI options for consumers.&lt;br&gt;Role Overview&lt;br&gt;We are looking for an energetic &lt;strong&gt;Banking Solutions Consultant (Manager - Banking Solutions)&lt;/strong&gt; with domain expertise in digital payments, bank gateway integrations, merchant acquiring, and pre-sales technical consulting. In this role, you will act as a solution evangelist\\u2014stitching together Razorpay\\u2019s product capabilities to solve stated and unstated business requirements for banks, alliance partners, and enterprise merchants. You will combine deep technical understanding with product and program management to lead solution discovery, design custom payment architectures, and drive integrations to deployment.&lt;br&gt;&lt;br&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;br&gt;Pre-Sales Consulting &amp;amp; Solution Discovery&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Present and demonstrate Razorpay\\u2019s unique value proposition during executive presentations and discovery sessions with prospective and existing bank partners and enterprise merchants.&lt;/li&gt;\\n&lt;li&gt;Map Razorpay\\u2019s product suite (Payment Gateway, POS, RazorpayX, Capital) and roadmap against customer requirements to design end-to-end payment architectures.&lt;/li&gt;\\n&lt;li&gt;Prepare functional scope documents (FSD), product requirement documents (PRD), and technical scope of work specifications for merchant acquiring solutions.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;Partner &amp;amp; Bank Co-Creation&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Partner with banks, card networks, and processors to co-create next-generation payment and banking solutions that address evolving merchant needs.&lt;/li&gt;\\n&lt;li&gt;Serve as the strategic bridge between Razorpay and external banking product and sales teams to drive ecosystem alignment.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;Platform &amp;amp; Program Delivery&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Manage and deliver merchant acquiring payment platforms across delivery channels including payment gateways, transaction processing, settlements, and dispute management.&lt;/li&gt;\\n&lt;li&gt;Collaborate internally with Razorpay&#39;s business, product, engineering, and customer success teams to translate requirements into scalable technical solutions.&lt;/li&gt;\\n&lt;li&gt;Facilitate support during UAT, certification testing, SDLC tracking, and platform troubleshooting across both issuing and acquiring frameworks.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;Relationship &amp;amp; Stakeholder Management&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Maintain proactive communication with bank leadership regarding product delivery roadmaps, platform upgrades, and feature rollouts.&lt;/li&gt;\\n&lt;li&gt;Drive conversations across cross-functional groups, resolve alignment conflicts, and maintain momentum across long-term project lifecycles.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;&lt;strong&gt;Qualifications &amp;amp; Skills&lt;/strong&gt;&lt;br&gt;Experience&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Minimum 5+ years of experience in pre-sales, technical consulting, product management, or platform delivery within digital payments, merchant acquiring, IT, or a leading financial institution.&lt;/li&gt;\\n&lt;li&gt;Prior experience at a fintech company with exposure to banks, or within a bank&#39;s product/payments team, is strongly preferred.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;Education&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;MBA graduate with a solid background in software technology and architecture.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;Domain &amp;amp; Technical Knowledge&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;In-depth understanding of payment products, merchant acquiring, payment gateways, transaction processing, card networks, settlement mechanics, and dispute workflows.&lt;/li&gt;\\n&lt;li&gt;Hands-on familiarity with end-to-end (ETED) transaction flows, SDLC processes, and system troubleshooting.&lt;/li&gt;\\n&lt;li&gt;Expertise in issuing and acquiring solutions offered to business partners.&lt;/li&gt;\\n&lt;li&gt;Exposure to payment network integrations (Visa, Mastercard, Rupay) and security certifications is a strong plus.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;div&gt;Core Competencies&lt;/div&gt;\\n&lt;ul&gt;\\n&lt;li&gt;&lt;strong&gt;Solution Evangelism:&lt;/strong&gt; Ability to synthesize complex technical features into intuitive business solutions.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Documentation &amp;amp; Presentation:&lt;/strong&gt; Exceptional documentation skills (PRDs, FSDs) and executive presentation capabilities.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Stakeholder Management:&lt;/strong&gt; Demonstrated ability to manage and influence internal product teams, external bank executives, and merchant partners.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Communication &amp;amp; Drive:&lt;/strong&gt; Outstanding written and verbal communication, high energy, adaptability, and conflict resolution capabilities across distributed teams&lt;/li&gt;\\n&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4021997005, \"name\": \"Banking Solutions\", \"child_ids\": [], \"parent_id\": 4021993005}], \"offices\": [{\"id\": 4024237005, \"name\": \"Razorpay POS\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.506559',NULL,'2026-10-07 15:54:44.506559',NULL,NULL,'2026-10-07 15:54:44.506559',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https://razorpay.com/careers/\"><meta name=\"description\" content=\"Join Razorpay — India\'s leading fintech powering mil