nt-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79xU6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+1F00-1FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4738319005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Banking Solutions',NULL,'Bengaluru','Group Manager, Banking Solutions'),(4932,'JOB_96f2fe45','Manager, AEO','Marketing',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-28T07:02:10-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4719411005','https://razorpay.com/careers/','2026-10-07T15:54:44.530786+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','7c6e7cc2c2673e2c377f6ec6150f1c66edf4c9476b9f16309b5b44e94db581ad','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4719411005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4719411005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4447142005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Bengaluru\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4719411005, \"updated_at\": \"2026-09-28T07:02:10-04:00\", \"requisition_id\": \"14554\", \"title\": \"Manager, AEO\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-09-01T02:49:18-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;h1&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;The Roles and Responsibilities:&lt;/strong&gt;&lt;/span&gt;&lt;/h1&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;AEO Strategy &amp;amp; Execution&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Develop and execute Razorpay\\u2019s AEO strategy aligned with AOP, quarterly goals, and monthly objectives , with clear KPIs around AI answer visibility, brand mention share, and citation rates.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build and maintain an AEO performance dashboard tracking Razorpay\\u2019s visibility across ChatGPT, Perplexity, Google AI Overviews, Gemini, and other answer engines.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Monitor AEO positioning across key payment platforms, tracking how leading domestic and global players are referenced in AI-generated responses.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Define and track Razorpay\\u2019s \\u201cAgentic Readiness Score\\u201d , measuring how well Razorpay\\u2019s website, docs, and content are structured for AI agent consumption.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Content Optimization for AI&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Audit and optimize Razorpay\\u2019s existing content (website, blog, docs, learn pages) for AI retrieval , ensuring structured data, clear entity relationships, and answer-ready formatting.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Develop content strategies specifically designed to win AI citations , including comparison pages, FAQ schemas, definitive guides, and structured product narratives.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Collaborate with the content team to create authoritative, entity-rich content that positions Razorpay as the primary source for payments and fintech topics in LLM training and retrieval.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Implement and maintain schema markup, structured data, and semantic HTML optimizations that improve AI comprehension of Razorpay\\u2019s content.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Develop guidelines for RAG-optimized content architecture \\u2014 defining how pages should be structured (header hierarchies, summary blocks, definition-first writing, explicit claim statements) so that retrieval systems consistently surface the most relevant Razorpay passage for a given query, rather than a competitor&#39;s.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Technical AEO &amp;amp; Website Readiness&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Work with engineering to ensure Razorpay\\u2019s website architecture supports AI crawlers, agents, and retrieval systems , including proper robots.txt directives, API endpoints for agentic access, and clean information architecture.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Conduct regular technical audits focused on AI readiness , crawlability by AI bots, structured data integrity, content freshness signals, and page experience metrics.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Optimize site speed, mobile experience, and Core Web Vitals as baseline requirements for both traditional SEO and AI answer eligibility.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Monitor and resolve technical issues impacting AI visibility , including indexing gaps, stale content, and broken structured data.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Own Razorpay\\u2019s agentic AI readiness , ensure all key surfaces (website, developer docs, pricing pages, product pages, integration guides) are structured for autonomous AI agents to navigate, extract information, and take action without human intervention.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Drive agentic AI onboarding readiness , work with Product and Engineering to ensure Razorpay\\u2019s signup, KYC, and merchant onboarding flows are parseable and completable by AI agents acting on behalf of prospective merchants, including structured form data, clear step sequencing, and machine-readable eligibility criteria.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Define and maintain agentic interface standards , including machine-readable sitemaps, API-accessible content layers, agent-friendly navigation patterns, and llms.txt or equivalent protocols that enable AI agents to understand and interact with Razorpay\\u2019s digital ecosystem.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;AEO Tool Stack &amp;amp; Measurement&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Evaluate, implement, and manage the AEO tool stack (e.g., Otterly.ai, Slate, Profound, Peec AI, and emerging platforms) for tracking AI answer visibility and brand mentions.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build measurement frameworks that quantify AEO impact on pipeline, traffic, and brand perception , establishing AEO as a reportable marketing channel.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Design and run experiments to test content formats, structural changes, and optimization tactics that improve AI answer outcomes.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Stay ahead of LLM ranking factors, retrieval-augmented generation (RAG) patterns, and AI search algorithm updates , translating them into actionable playbooks.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Own Razorpay&#39;s GA4 implementation as it relates to AEO and organic performance, including custom event tracking, conversion path analysis, channel grouping configurations, and funnel attribution \\u2014 to accurately measure how AI-referred and organic traffic behaves across Razorpay&#39;s product pages, docs, and sign-up flows.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build GA4-based reporting layers that connect AEO visibility metrics (AI citations, answer impressions) to downstream business outcomes (sessions, sign-up initiations, product page depth), enabling leadership to see AEO&#39;s contribution to pipeline. not just traffic.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;AI-Powered Automation &amp;amp; Workflows&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Design and build automated SEO/AEO dashboards that pull data from multiple sources (Google Search Console, Ahrefs, AEO tracking tools, GA4) into unified, real-time views , eliminating manual reporting overhead.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build AI-driven content generation workflows , automated brief creation, first-draft generation, meta tag optimization, and bulk content updates powered by LLMs with human-in-the-loop quality gates.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Create automated recommendation engines that surface SEO/AEO optimization opportunities , flagging underperforming pages, suggesting content gaps, recommending internal linking improvements, and prioritizing fixes by impact.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build end-to-end workflow automations using AI tools, APIs, and platforms (e.g., Zapier, Make.com, n8n, Claude API, custom scripts) to streamline repetitive SEO/AEO operations across content, technical, and reporting functions.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Automate content refresh and decay detection workflows , identifying stale content, triggering update cycles, and auto-generating refresh briefs based on search trend shifts and AI answer changes.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Create self-serve automation templates that enable the broader marketing team to run SEO/AEO tasks (keyword research, content audits, performance pulls) without manual intervention.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Continuously identify automation opportunities across the SEO/AEO function , with a target of reducing manual effort by 50%+ within the first year through intelligent automation.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Cross-Functional Collaboration&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Collaborate with SEO, Performance Marketing, Brand, and Product Marketing teams to ensure AEO strategy is integrated with broader marketing efforts.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Work with Product and Engineering teams on developer documentation optimization , a critical surface for AI-driven recommendations in the payments space.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Manage relationships with external SEO/AEO vendors, consultants, and platform providers.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Present AEO performance reports, insights, and strategic recommendations to senior leadership including CPO and CMO.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h1&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;span style=&quot;font-size: 16px;&quot;&gt;Mandatory Skills:&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;5 to 7 years of experience in SEO, with at least 1-2 years of direct exposure to AEO, AI search optimization, or LLM-related content strategy.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Deep understanding of how LLMs (GPT, Gemini, Claude, Llama) retrieve, rank, and cite web content , including RAG systems, knowledge graphs, and entity recognition.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Hands-on experience building automation workflows and AI agents using AI tools, APIs, and platforms (Zapier, Make.com, n8n, Python scripting, or similar) , not just using tools, but architecting end-to-end automated pipelines.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Deep hands-on experience with GA4, custom dimensions, event schema design, funnel exploration, attribution modelling, and Looker Studio or BigQuery integration for advanced reporting. Ability to go beyond out-of-the-box reports and build measurement frameworks that accurately reflect non-linear, multi-touch journeys typical of B2B fintech discovery.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Proven ability to build dashboards and automated reporting systems , pulling data from multiple sources into unified views using tools like Looker Studio, Tableau, Google Sheets with APIs, or custom solutions.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Strong technical SEO foundation , site architecture, JavaScript for SEO/AEO, crawl optimization, and mobile-first indexing.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Experience with AI-powered content generation and SEO workflows , using AI Agents for automated brief creation, content drafting, meta tag generation, or bulk optimization at scale.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Hands-on experience with SEO tools (Ahrefs, SEMrush, Screaming Frog, Google Search Console) and emerging AEO tools (Otterly.ai, Profound, or similar).&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Strong communication skills with the ability to present to senior leadership and influence cross-functional stakeholders.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Experience in B2B SaaS, fintech, or payments is &lt;strong&gt;strongly preferred&lt;/strong&gt;.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;strong&gt;Good to Have&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Bachelor&#39;s degree in Engineering, Computer Science, or a related technical field, given the role&#39;s hands-on requirements around automation pipelines, API integrations, and RAG-layer content architecture, a foundational technical education accelerates ramp-up significantly.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Experience with content strategy for developer audiences (API docs, technical guides, integration tutorials).&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Familiarity with AI/ML fundamentals , understanding of embeddings, vector search, and how AI models process content.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Proficiency in Python or JavaScript for custom automation scripts, API integrations, and data pipelines.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Experience with Claude API, OpenAI API, or similar LLM APIs for building production-grade content and recommendation workflows.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Experience managing external agencies or vendors in an SEO/content capacity.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;People management experience , ability to lead and mentor a small team as the AEO function scales.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Track record of experimentation , designing A/B tests, content experiments, and iterating based on data.&lt;/span&gt;&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Experience with MCP (Model Context Protocol), AI agents, or agentic workflow frameworks.&lt;/span&gt;&lt;/li&gt;\\n&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4024764005, \"name\": \"Marketing\", \"child_ids\": [4134241005, 4024767005, 4024771005, 4024773005, 4024765005, 4024772005, 4024766005, 4024769005, 4024768005, 4024770005, 4024774005, 4024775005, 4149360005], \"parent_id\": 4021992005}], \"offices\": [{\"id\": 4009555005, \"name\": \"Payments\", \"loc