y: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79xU6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+1F00-1FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4727238005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Banking Alliances',NULL,'Bengaluru','Manager, Banking Alliances'),(4935,'JOB_0a1b0132','Manager, Banking Solutions','Banking Solutions',NULL,'Mumbai',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-01T06:12:07-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4738327005','https://razorpay.com/careers/','2026-10-07T15:54:44.606509+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','38d57260b81c4e169116b1d9f1e049f76e2ba2f8b1ec78a9c4cd86ac982cc961','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4738327005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4738327005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4456658005, \"location\": {\"name\": \"Mumbai\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Mumbai\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Mumbai\", \"value_type\": \"single_select\"}], \"id\": 4738327005, \"updated_at\": \"2026-10-01T06:12:07-04:00\", \"requisition_id\": \"14771\", \"title\": \"Manager, Banking Solutions\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-09-29T01:01:43-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/h3&gt;\\n&lt;p&gt;The &lt;strong&gt;UPI \\u2013 Banking Solutions Manager&lt;/strong&gt; position exists to own and drive Razorpay&#39;s end-to-end UPI infrastructure, NPCI + Bank partner relationships, and payment rail maintenance + integrations within the Banking Solutions unit. As the core domain leader for UPI solutions, this role solves complex product and technical bottlenecks between partner banks, NPCI, and internal payment switches to maximize transaction success rates, minimize latency, and scale high-concurrency payment flows. Reporting into Banking Solutions leadership, this lead-level position sits at the intersection of transaction banking, product architecture, and regulatory execution to pioneer new UPI initiatives (such as UPI MDR, Agentic Payments - UAP, UPI Credit Line, AutoPay, and Cross-Border UPI).&lt;/p&gt;\\n&lt;h3&gt;&lt;strong&gt;Roles &amp;amp; Responsibilities&lt;/strong&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li&gt;&lt;strong&gt;Own and manage end-to-end UPI charter with Banks &amp;amp; Networks&lt;/strong&gt;, sponsor bank relationships, and NPCI (+ NIPL) relationships for all things UPI.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Drive UPI transaction success rates, system uptime, and latency optimization&lt;/strong&gt; across all partner bank gateway/ switches.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;UPI Switch Management: &lt;/strong&gt;Lead all marquee product feature developments and deployments, building unique value propositions on Razorpay Switches.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Spearhead the execution of advanced UPI payment innovations&lt;/strong&gt;, including Credit Line on UPI, UPI Lite, AutoPay, and international payment flows.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Partner with bank technology leadership, regulatory bodies, and internal product teams&lt;/strong&gt; to design resilient, scalable, and compliant switch architectures.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Lead root-cause analysis (RCA) and mitigation frameworks&lt;/strong&gt; for transaction drops, downtime incidents, and partner bank infrastructure degradation.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Leverage AI-driven payment routing tools and predictive analytics&lt;/strong&gt; to monitor real-time transaction health, detect anomalies, and dynamically optimize traffic distribution.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;strong&gt;Mandatory Qualifications&lt;/strong&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li&gt;&lt;strong&gt;Experience:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;&lt;strong&gt;4\\u20138 years of experience&lt;/strong&gt; in Fintech, Digital Payments, or Transaction Banking, with at least &lt;strong&gt;2+ years of dedicated expertise in UPI payments - product/ tech&lt;/strong&gt;.&lt;/li&gt;\\n&lt;li&gt;Proven track record of managing high-volume payment rails, success rate optimization, and switch performance engineering.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;Skills:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;In-depth understanding of &lt;strong&gt;NPCI UPI specifications, payment switch mechanics, API protocols, and nodal/escrow account operations&lt;/strong&gt;.&lt;/li&gt;\\n&lt;li&gt;Strong partner management, technical negotiation, and cross-functional leadership capabilities across banking and regulatory stakeholders.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;Tools:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Proficiency with &lt;strong&gt;SQL, log analysis frameworks (Kibana/Grafana), API testing suites (Postman), and payment analytics platforms&lt;/strong&gt;.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;AI Builder &amp;amp; Digital Competency:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Practical capability in utilizing &lt;strong&gt;AI-powered transaction routing engines, predictive uptime monitoring platforms, and automated anomaly detection workflows&lt;/strong&gt; to maintain high-availability payment rails.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=