\');\r\n  unicode-range: U+1F00-1FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4729533005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Product Management',NULL,'Bengaluru','Product Manager II - Ads '),(4938,'JOB_a9b20cb6','Senior Associate, HRBP Operations','People Operations',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-07T04:14:51-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4739576005','https://razorpay.com/careers/','2026-10-07T15:54:44.713362+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','5d9a8daf68dd8392226941bb706b742e1789a2a61d13917d7a1c8ef0d06ed4fb','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4739576005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4739576005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4457288005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Bengaluru\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4739576005, \"updated_at\": \"2026-10-07T04:14:51-04:00\", \"requisition_id\": \"14782\", \"title\": \"Senior Associate, HRBP Operations\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-10-05T02:18:55-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Role Summary&lt;/strong&gt;&lt;/p&gt;\\n&lt;p&gt;We are looking for an organised, proactive and detail-oriented HR professional to support the HRBP team across people initiatives, employee engagement, data and reporting, communications and day-to-day operations. The role will work closely with HRBPs and cross-functional teams to ensure seamless execution of people initiatives and enable a smooth employee experience.&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Roles &amp;amp; Responsibilities&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;&lt;strong&gt;HRBP Enablement:&lt;/strong&gt; Provide day-to-day operational support to HRBPs, including scheduling, follow-ups, trackers and coordination across ongoing people initiatives.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;People Initiatives &amp;amp; Engagement:&lt;/strong&gt; Plan and execute employee engagement initiatives, All Hands, town halls and other HR events, owning the end-to-end coordination and logistics.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Communication &amp;amp; Presentation Support:&lt;/strong&gt; Create and support HR communications, leadership decks, All Hands presentations and other employee-facing collaterals.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Data &amp;amp; Reporting:&lt;/strong&gt; Maintain HR dashboards and trackers, support basic data analysis and prepare People &amp;amp; Culture reports and insights for leadership reviews.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Cross-functional &amp;amp; Vendor Coordination:&lt;/strong&gt; Work with Finance, CREWs, Payroll, Benefits and other stakeholders on HR-related requirements, including procurement, invoices, vendor payments and employee milestone requirements.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;Process Improvement:&lt;/strong&gt; Support the HRBP team in streamlining recurring processes, improving trackers and ways of working, and driving operational efficiency.&lt;/li&gt;\\n&lt;li&gt;&lt;strong&gt;End-to-end Ownership:&lt;/strong&gt; Take ownership of assigned HR initiatives from planning through execution and closure, ensuring timely follow-ups and stakeholder alignment.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;strong&gt;Mandatory Qualifications&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Bachelor&#39;s degree in any discipline.&lt;/li&gt;\\n&lt;li&gt;1\\u20133 years of experience in HR Operations, HR Coordination, People Operations or a similar role.&lt;/li&gt;\\n&lt;li&gt;Strong proficiency in &lt;strong&gt;Excel / Google Sheets&lt;/strong&gt;, including trackers, dashboards and basic data analysis.&lt;/li&gt;\\n&lt;li&gt;Good &lt;strong&gt;presentation and visual communication skills&lt;/strong&gt;; proficiency in PowerPoint/Google Slides. Basic Canva/design skills would be an advantage.&lt;/li&gt;\\n&lt;li&gt;Excellent organisational skills with the ability to manage multiple priorities and timelines.&lt;/li&gt;\\n&lt;li&gt;Proactive, detail-oriented and comfortable working in a fast-paced environment.&lt;/li&gt;\\n&lt;li&gt;Strong ownership and ability to independently drive tasks to closure.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&lt;strong&gt;Note: This is a Contract Role&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4024785005, \"name\": \"People Operations\", \"child_ids\": [4035817005, 4024787005, 4024786005, 4024788005, 4024789005, 4024790005, 4042579005], \"parent_id\": 4021992005}], \"offices\": [{\"id\": 4009552005, \"name\": \"Corporate\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.713362',NULL,'2026-10-07 15:54:44.713362',NULL,NULL,'2026-10-07 15:54:44.713362',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https:/