U+2116;\r\n}\r\n/* greek-ext */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79xU6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+1F00-1FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4739576005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'People Operations',NULL,'Bengaluru','Senior Associate, HRBP Operations'),(4939,'JOB_969f64be','Senior Associate, Learning Business Partner','Learning and Development',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-07T07:19:11-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740305005','https://razorpay.com/careers/','2026-10-07T15:54:44.739599+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','928d32597c61a2a54957516bae3d47263c4c3785fc55d9c8e892da10_4939','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740305005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4740305005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4457659005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Bengaluru\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4740305005, \"updated_at\": \"2026-10-07T07:19:11-04:00\", \"requisition_id\": \"14784\", \"title\": \"Senior Associate, Learning Business Partner\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-10-07T02:11:18-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;Role Overview&lt;/h2&gt;\\n&lt;p&gt;We are looking for a highly organised and collaborative Learning Business Partner (LBP) to support our Business Functions. In this role, you will be responsible for end-to-end training operations, from identifying skill gaps through stakeholder management to executing monthly training calendars. You will act as a key liaison, ensuring that our teams have the resources they need to grow and succeed.&lt;/p&gt;\\n&lt;h2&gt;Key Responsibilities&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li&gt;AI - Native Business Function: As an LBP, your mission is to design and execute our AI-Native strategy. You will champion the integration of artificial intelligence across all core business functions. Your goal is to maximise operational intelligence, streamline team velocity, and future-proof our business function.&lt;/li&gt;\\n&lt;li&gt;Learning the Ground Reality: Spend time working closely with the teams to see how they actually do their jobs. This helps you understand business goals and the real challenges employees face every day.&lt;/li&gt;\\n&lt;li&gt;Spotting the Gaps (Training Need Identification): Talk to managers to find out where the team is struggling. Use what you learned &quot;on the ground&quot; to suggest the right training sessions to solve those problems.&lt;/li&gt;\\n&lt;li&gt;Creating the Plan: Once you know what\\u2019s needed, build the training plan. You&#39;ll decide how the training will work and get feedback from leaders to make sure the plan is perfect.&lt;/li&gt;\\n&lt;li&gt;Making it Happen: Be the person in charge of running the training. This means managing the calendar, sending out invites, and making sure everything goes smoothly on the day of the session.&lt;/li&gt;\\n&lt;li&gt;Managing the Tools: Use our learning apps (LMS) to upload training videos or documents and keep track of who has finished their lessons.&lt;/li&gt;\\n&lt;li&gt;Proving the Results: Show that the training worked! You\\u2019ll need to have the data (numbers) ready to show how many people attended, what they thought of it, and how it improved their work.&lt;/li&gt;\\n&lt;li&gt;Stakeholder Management: Meet regularly with department heads to understand their goals and build strong working relationships across the company.&lt;/li&gt;\\n&lt;li&gt;Vendor Management: Find outside training experts, handle the paperwork and payments, and make sure their workshops run smoothly from start to finish.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h2&gt;Mandatory Qualifications &amp;amp; Skills&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Experience: Previous work in a training or L&amp;amp;D role (2-3 years) where you managed multiple tasks at once.&lt;/li&gt;\\n&lt;li&gt;People Skills: The ability to talk comfortably with everyone from junior staff to leadership.&lt;/li&gt;\\n&lt;li&gt;Organisation: A person who is very detail-oriented and never misses a deadline on the assigned projects.&lt;/li&gt;\\n&lt;li&gt;AI tools: Comfortable in using modern AI and development tools like Gemini, Claude, GPT, etc., can use them for daily use, automate mundane tasks and focus on new initiatives.&lt;/li&gt;\\n&lt;li&gt;Strong skills in Google Workspace to manage data, track performance numbers, and present actionable insights to leadership during regular reviews&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4024788005, \"name\": \"Learning and Development\", \"child_ids\": [], \"parent_id\": 4024785005}], \"offices\": [{\"id\": 4009552005, \"name\": \"Corporate\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.739599',NULL,'2026-10-07 15:54:44.739599',NULL,NULL,'2026-10-07 15:54:44.739599',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<ht