ramond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79xU6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+1F00-1FFF;\r\n}\r\n/* greek */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n  font-weight: 700;\r\n  font-display: swap;\r\n  src: url(https://fonts.gstatic.com/s/ebgaramond/v33/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR79-U6ingQ.woff2) format(\'woff2\');\r\n  unicode-range: U+0370-0377, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4731060005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Finance',NULL,'Bengaluru','Senior Executive, Finance'),(4941,'JOB_10aea52e','Senior Manager, Sales','SME Sales',NULL,'Singapore',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-28T07:02:10-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4709725005','https://razorpay.com/careers/','2026-10-07T15:54:44.786870+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','f399f446eb48f21efaf7c026a7f936b20e6a78fd903b91050909f417_4941','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4709725005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4709725005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4442600005, \"location\": {\"name\": \"Singapore\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Singapore\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Singapore\", \"value_type\": \"single_select\"}], \"id\": 4709725005, \"updated_at\": \"2026-09-28T07:02:10-04:00\", \"requisition_id\": \"14390\", \"title\": \"Senior Manager, Sales\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-06-26T06:07:59-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the role:&lt;/strong&gt;&lt;/p&gt;\\n&lt;p&gt;We are looking for a motivated and passionate Sales Manager to join the South East Asia Business. Joining Razorpay at this early stage offers an exciting opportunity to be part of a dynamic team and shape the future of digital payments in the region. If you have the drive to make a meaningful impact within the industry, we invite you to apply for this role and contribute to Razorpay&#39;s journey in becoming the leading fintech partner in the market.&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Key Role &amp;amp; Responsibilities:&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Achieve sales targets consistently and strive hard to challenge the competition landscape in the industry&lt;/li&gt;\\n&lt;li&gt;Build, maintain and forecast a healthy sales pipeline to achieve business goals&lt;/li&gt;\\n&lt;li&gt;Own the end-to-end sales cycle while working collaboratively with Marketing, Onboarding, Integration and other internal stakeholders&lt;/li&gt;\\n&lt;li&gt;Should be responsible for understanding all client requirements &amp;amp; propose a suitable solution using Razorpay payment products and services&lt;/li&gt;\\n&lt;li&gt;Energetic self-starter with the ability to work independently in a fast-paced environment with a proven track record.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Mandatory Qualifications:&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;5-10 years of overall experience in Merchant acquiring space with either payment gateways, acquirers, or Fintech companies&lt;/li&gt;\\n&lt;li&gt;Established and existing network of merchants with SME and Middle Market client base in Singapore&lt;/li&gt;\\n&lt;li&gt;&amp;nbsp;Strong communication, oral &amp;amp; written skills&lt;/li&gt;\\n&lt;li&gt;&amp;nbsp;Highly self-motivated and result-oriented personality&lt;/li&gt;\\n&lt;li&gt;Strong interpersonal skills and an ability to build rapport with customers&lt;/li&gt;\\n&lt;li&gt;Hardworking person with a strong work ethic&lt;/li&gt;\\n&lt;li&gt;Ability to leverage AI to drive competitive advantage and improve productivity&lt;/li&gt;\\n&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4024792005, \"name\": \"SME Sales\", \"child_ids\": [], \"parent_id\": 4040706005}], \"offices\": [{\"id\": 4024236005, \"name\": \"I18N\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.786870',NULL,'2026-10-07 15:54:44.786870',NULL,NULL,'2026-10-07 15:54:44.786870',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https://razorpay.com/careers/\"><meta name=\"description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engineering, product, design, marketing &amp; more for freshers and experienced professionals.\">\r\n    <meta name=\"framer-search-index\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-4DmOEMu4PQhg.json\">\r\n    <meta name=\"framer-search-index-fallback\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-aFxS1y2nLCaA.json\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: light)\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: dark)\">\r\n    <!-- Open Graph -->\r\n    <meta property=\"og:type\" content=\"websit