L,NULL,0,NULL,'4729051005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'Solutions',NULL,'Bengaluru','Senior Solutions Consultant'),(4945,'JOB_0f5906ba','Senior Territory Manager, Bank Retail & Direct Enterprise Sales','GTM Offline First',NULL,'Chennai',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-28T07:02:10-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4736132005','https://razorpay.com/careers/','2026-10-07T15:54:44.883760+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','309432d1bb82bb64427eb0ab2bd5d44935dfaeb9f6908c248459e430_4945','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4736132005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4736132005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4455440005, \"location\": {\"name\": \"Chennai\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Chennai\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4736132005, \"updated_at\": \"2026-09-28T07:02:10-04:00\", \"requisition_id\": \"14723\", \"title\": \"Senior Territory Manager, Bank Retail & Direct Enterprise Sales\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-09-21T06:10:45-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Role Summary&lt;/span&gt;&lt;/h2&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;The Territory Sales Manager (TSM) / Senior Territory Sales Manager (Sr. TSM) will be responsible for driving merchant acquisition and revenue growth across the assigned territory. The role involves managing relationships with Retail merchants, Enterprise customers, Aggregators, and Banking partners while ensuring seamless onboarding, deployment, and portfolio management of Razorpay&#39;s Offline Payment Solutions.&lt;/span&gt;&lt;/p&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;The incumbent will focus on&lt;strong&gt;&amp;nbsp;new business acquisition (Hunting)&lt;/strong&gt;&amp;nbsp;and&lt;strong&gt;&amp;nbsp;relationship management &amp;amp; portfolio growth (Farming)&lt;/strong&gt;, while collaborating closely with internal cross-functional teams to deliver an exceptional merchant experience.&lt;/span&gt;&lt;/p&gt;\\n&lt;h2&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Key Responsibilities&lt;/span&gt;&lt;/h2&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Business Development&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Drive sales of Razorpay Offline Payment Solutions across the assigned territory.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Achieve monthly, quarterly, and annual sales and deployment targets.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Identify and acquire new merchants across Retail, SME, Mid-Market, and Enterprise segments.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build a strong pipeline through field sales, referrals, banking channels, and partner networks.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Generate consistent business opportunities through market mapping and prospecting.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Merchant Acquisition &amp;amp; Onboarding&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Acquire new merchants for Razorpay POS, Soundbox (SB), and Payment Gateway (PG), wherever applicable.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Manage the complete sales cycle from lead generation to onboarding and activation.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Ensure timely documentation, KYC completion, installation, and merchant activation.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Coordinate internally to ensure smooth merchant onboarding and faster turnaround times.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Relationship &amp;amp; Portfolio Management&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Manage the assigned merchant portfolio and ensure high merchant engagement.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build strong long-term relationships with existing merchants.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Drive cross-sell and upsell opportunities across Razorpay&#39;s payment solutions.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Improve merchant retention and transaction growth within the portfolio.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Conduct periodic merchant visits and business reviews.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Banking Relationship Management&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Develop and maintain strong working relationships with partner bank branches and sales teams.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Generate quality merchant referrals through banking partnerships.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Conduct joint customer meetings and business development initiatives with bank stakeholders.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Ensure effective engagement with banking partners to maximize business opportunities.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Aggregator &amp;amp; Enterprise Business&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Build relationships with aggregators, franchise networks, and enterprise customers.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Identify opportunities to onboard key enterprise accounts within the territory.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Coordinate with internal enterprise and solution teams to ensure successful implementation.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Cross-Functional Coordination&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Work closely with Operations, Product, Risk, Finance, Customer Success, and Installation teams.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Ensure timely merchant onboarding, deployment, and issue resolution.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Escalate and resolve merchant concerns to maintain a superior customer experience.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Provide market feedback to internal teams for continuous product improvement.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Market Development&lt;/span&gt;&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Track competitor activities, pricing, and market trends.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Identify new business opportunities and emerging market segments.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Execute local sales campaigns and merchant engagement activities.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Increase Razorpay&#39;s visibility and market share within the assigned territory.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h2&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Desired Candidate Profile&lt;/span&gt;&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;8\\u201310 years of experience in Merchant Acquiring, FinTech, Banking, Payment Solutions, POS Sales, or Financial Services.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Proven experience in field sales and merchant acquisition.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Strong exposure to Retail, SME, Enterprise, Aggregator, and Banking channels.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Good understanding of POS acquiring, Soundbox, QR, and Payment Gateway solutions.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Excellent relationship management, negotiation, and communication skills.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Strong ownership mindset with the ability to work independently in a target-driven environment.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Willingness to travel extensively within the assigned territory.&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h2&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Preferred Industry Experience&lt;/span&gt;&lt;/h2&gt;\\n&lt;ul&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Merchant Acquiring&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;\\n&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;FinTech&lt;/span&gt;&lt;/p&gt;\\n&lt;/li&gt;\\n&lt;li style