7, U+037A-037F, U+0384-038A, U+038C, U+038E-03A1, U+03A3-03FF;\r\n}\r\n/* vietnamese */\r\n@font-face {\r\n  font-family: \'EB Garamond\';\r\n  font-style: italic;\r\n ',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,NULL,NULL,NULL,NULL,0,NULL,'4736132005',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{}','ats_direct_greenhouse','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\", \"raw_department\": \"department\"}',NULL,'{}',NULL,'GTM Offline First',NULL,'Chennai','Senior Territory Manager, Bank Retail & Direct Enterprise Sales'),(4946,'JOB_afd6f8b8','Site Reliability Engineer','Engineering',NULL,'Bengaluru',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-06T04:20:13-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4723040005','https://razorpay.com/careers/','2026-10-07T15:54:44.922802+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','397c99d6e5f5059e661ab75649da0985ba2d23208569dc6d6b6f0868cdf8f765','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4723040005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4723040005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4448971005, \"location\": {\"name\": \"Bengaluru\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Bengaluru\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Bengaluru\", \"value_type\": \"single_select\"}], \"id\": 4723040005, \"updated_at\": \"2026-10-06T04:20:13-04:00\", \"requisition_id\": \"14592\", \"title\": \"Site Reliability Engineer\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-09-24T11:03:10-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;About the role&lt;/h3&gt;\\n&lt;p&gt;You will be one of the founding SREs at Razorpay, embedded with the payment platform teams that move money for millions of businesses. Your mandate is to take our payment flows from three nines to four and five nines of availability. In payments, a failed request is not a retry, it is a customer&#39;s money in limbo. You will define what reliability means here, build the systems that enforce it, and set the standard every future SRE is measured against.&lt;/p&gt;\\n&lt;h3&gt;What you will do&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Define SLIs, SLOs, and error budgets for critical payment flows (authorization, capture, refunds, settlements, webhooks) and make them the shared language between product and platform teams.&lt;/li&gt;\\n&lt;li&gt;Own the release lifecycle for payment services: design progressive rollout pipelines (canary, staged, feature-flagged), automated rollback triggers, and make &quot;can we roll back in under 5 minutes&quot; a launch-blocking question.&lt;/li&gt;\\n&lt;li&gt;Carry the pager for payment-critical services, lead incident command during outages, and drive blameless postmortems where action items actually ship.&lt;/li&gt;\\n&lt;li&gt;Eliminate toil through software: build automation for failover, capacity management, load shedding, and degradation so that known failure classes cannot recur.&lt;/li&gt;\\n&lt;li&gt;Harden payment flows against distributed systems failure modes: retry storms, thundering herds, cascading failures, partial outages of banks and network partners, idempotency violations, and reconciliation gaps.&lt;/li&gt;\\n&lt;li&gt;Run production readiness reviews for new payment services and hold the line on launch gates using error budget data, not opinion.&lt;/li&gt;\\n&lt;li&gt;Instrument what matters: design alerting that pages on customer-facing symptoms, not noise, and cut mean time to detection and recovery quarter over quarter.&lt;/li&gt;\\n&lt;li&gt;Practice failure on purpose: game days, chaos experiments, and failure injection against payment-critical paths.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;What we are looking for&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li&gt;10+ years of engineering experience, with at least 5 years operating large-scale distributed systems in production (high QPS, multi-region, or systems where sub-1 percent error rates were business-critical).&lt;/li&gt;\\n&lt;li&gt;Strong software engineering skills in at least one of Go, Java, or Python. You have built tools and services, not just configured them.&lt;/li&gt;\\n&lt;li&gt;Deep understanding of distributed systems failure modes and the patterns that contain them: circuit breakers, backpressure, bulkheading, graceful degradation, idempotency.&lt;/li&gt;\\n&lt;li&gt;Solid fundamentals in Linux internals, networking, and databases under load (replication, failover, connection pool exhaustion, lock contention).&lt;/li&gt;\\n&lt;li&gt;Hands-on experience designing or significantly improving deployment pipelines: canary analysis, automated rollback, feature flags.&lt;/li&gt;\\n&lt;li&gt;Genuine on-call ownership: you have carried a pager for systems that mattered, led incidents, and can walk us through a specific outage you handled and what you changed afterward.&lt;/li&gt;\\n&lt;li&gt;Fluency with modern observability (metrics, tracing, structured logging; e.g. Prometheus, Grafana, OpenTelemetry, Datadog, Coralogix, Clickhouse or similar) and experience reducing alert noise.&lt;/li&gt;\\n&lt;li&gt;Experience defining SLOs and error budget policies from scratch. Contributions to reliability tooling, open source or internal, that other teams adopted.&lt;/li&gt;\\n&lt;li&gt;The judgment and communication skills to tell a product team &quot;not yet&quot; with data, and the pragmatism to help them get to &quot;yes&quot; quickly.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;h3&gt;Nice to have&lt;/h3&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Experience in payments, fintech, banking, trading, or another domain where correctness and money are coupled (transactional consistency, exactly-once semantics, reconciliation).&lt;/li&gt;\\n&lt;li&gt;Experience with Kubernetes at scale, service mesh, and traffic management.&lt;/li&gt;\\n&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4024806005, \"name\": \"Engineering\", \"child_ids\": [4024813005, 4134592005, 4040417005, 4024815005, 4037762005, 4037761005, 4024821005, 4024807005, 4024808005, 4024809005, 4024810005, 4024812005, 4024818005, 4024811005, 4024814005, 4024816005, 4024820005, 4024817005, 4024819005], \"parent_id\": null}], \"offices\": [{\"id\": 4009826005, \"name\": \"DevSecOps\", \"location\": null, \"child_ids\": [], \"parent_id\": null}], \"ai_disclaimer\": null, \"include_ai_disclaimer\": null, \"ai_opt_out_request_url\": null}','ATS_API','2026-10-07 15:54:44.922802',NULL,'2026-10-07 15:54:44.922802',NULL,NULL,'2026-10-07 15:54:44.922802',NULL,'<!doctype html>\r\n<!-- Made in Framer · framer.com ✨ -->\r\n<!-- Published Sep 30, 2026, 6:37 AM UTC -->\r\n<html lang=\"en-IN\">\r\n<head>\r\n	<meta charset=\"utf-8\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">\r\n	<meta name=\"generator\" content=\"Framer 29d393b\">\r\n	<title>Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay</title>\r\n    <link rel=\"canonical\" href=\"https://razorpay.com/careers/\"><meta property=\"og:url\" content=\"https://razorpay.com/careers/\"><meta name=\"description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engineering, product, design, marketing &amp; more for freshers and experienced professionals.\">\r\n    <meta name=\"framer-search-index\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-4DmOEMu4PQhg.json\">\r\n    <meta name=\"framer-search-index-fallback\" content=\"https://framerusercontent.com/sites/2nUU1f6TICUTYaR72R1wDr/searchIndex-aFxS1y2nLCaA.json\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: light)\">\r\n    <link href=\"https://framerusercontent.com/images/CU1m0xFonUl76ZeaW0IdkQ0M.png\" rel=\"icon\" media=\"(prefers-color-scheme: dark)\">\r\n    <!-- Open Graph -->\r\n    <meta property=\"og:type\" content=\"website\">\r\n    <meta property=\"og:title\" content=\"Razorpay Careers | Jobs, Hiring &amp; Career Opportunities at Razorpay\">\r\n    <meta property=\"og:description\" content=\"Join Razorpay — India\'s leading fintech powering millions of businesses. Explore openings in engi