epartment\"}',NULL,'{}',NULL,'Engineering',NULL,'Bengaluru','Site Reliability Engineer'),(4947,'JOB_92128ca3','Solutions Consultant','Business',NULL,'Malaysia',NULL,'India',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-28T07:02:10-04:00',NULL,'https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4721391005','https://razorpay.com/careers/','2026-10-07T15:54:44.952118+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API)','1bb3c299840528384d07045df16e92f2fc299b8b31c8063dd162d91b_4947','COMP_0','https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4721391005','a1894d96685103401d7d32629571db8c',NULL,'{\"absolute_url\": \"https://job-boards.greenhouse.io/razorpaysoftwareprivatelimited/jobs/4721391005\", \"data_compliance\": [{\"type\": \"gdpr\", \"requires_consent\": false, \"requires_processing_consent\": false, \"requires_retention_consent\": false, \"retention_period\": null, \"demographic_data_consent_applies\": false}], \"employment\": \"employment_required\", \"internal_job_id\": 4448155005, \"location\": {\"name\": \"Malaysia\"}, \"metadata\": [{\"id\": 4731492005, \"name\": \"Job Location\", \"value\": [\"Malaysia\"], \"value_type\": \"multi_select\"}, {\"id\": 9708137005, \"name\": \"Job Location ( Base Location )\", \"value\": \"Malaysia\", \"value_type\": \"single_select\"}], \"id\": 4721391005, \"updated_at\": \"2026-09-28T07:02:10-04:00\", \"requisition_id\": \"14565\", \"title\": \"Solutions Consultant\", \"company_name\": \"Razorpay Software Private Limited\", \"first_published\": \"2026-08-06T02:20:46-04:00\", \"language\": \"en\", \"application_deadline\": null, \"content\": \"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Razorpay is one of India\\u2019s leading full-stack financial technology companies, powering the way businesses move, manage, and grow money. Founded in 2014 by Harshil Mathur and Shashank Kumar with a simple vision - to simplify payments for Indian businesses - we\\u2019ve since grown into a fintech powerhouse driving India\\u2019s digital payment revolution.&lt;/p&gt;\\n&lt;p&gt;Razorpay powers millions of businesses with a smarter, scalable stack that goes beyond transactions to help them truly build and grow.&lt;/p&gt;\\n&lt;p&gt;From building AI-native agentic payments, to AI-assisted fraud detection and real-time risk intelligence to automated reconciliation, smart payouts, and predictive financial insights, we are embedding intelligence across our stack to make money movement faster, safer, and more efficient. In close collaboration with ecosystem partners - including banks, networks, regulators - we are pioneering industry-first solutions that are shaping the next era of fintech&lt;/p&gt;\\n&lt;p&gt;Across India, Singapore and Malaysia, our products span everything from seamless checkouts to payroll automation - powering a fintech ecosystem that\\u2019s redefining how money moves across Asia.&lt;/p&gt;\\n&lt;p&gt;Today, that ecosystem supports everyone from early-stage startups to some of India\\u2019s largest enterprises, enabling them to accept, process, and disburse payments at scale while expanding into new ways of managing money more efficiently.&lt;/p&gt;\\n&lt;p&gt;Our scale speaks volumes: Razorpay processes $180+ billion in annualized transactions, powering leading businesses like Airbnb, Facebook, WhatsApp, Airtel, CRED, BookmyShow, Zomato, Swiggy, Lenskart, Mirae Asset Capital markets, Indian Oil, National Pension Scheme - and over 100 of India\\u2019s unicorns. With strong roots in India and growing operations in Southeast Asia, we are shaping the next chapter of financial technology across the region.&lt;/p&gt;\\n&lt;p&gt;We are backed by global investors including GIC, Peak XV Partners (formerly Sequoia Capital India &amp;amp; SEA), Tiger Global, Ribbit Capital, Matrix Partners, MasterCard, and Salesforce Ventures, having raised over $740 million to date. Strategic acquisitions - including Ezetap (POS and offline payments), Curlec (Malaysia expansion), BillMe (digital invoicing), and POP (rewards-first UPI) - along with earlier moves in fraud prevention, payroll, and lending, have further strengthened our platform and widened our footprint across Asia.&lt;/p&gt;\\n&lt;p&gt;But what truly sets Razorpay apart is our culture. At Razorpay, ownership is our oxygen - you own what you build, with no micromanagement or red tape, just the runway to make your ideas fly. Learning is a lifestyle - if you\\u2019re curious, you\\u2019ll feel at home here. People &amp;gt; Pedigree - we hire for attitude, hustle, and hunger more than degrees. Transparency thrives over titles - this is where interns question CXOs and CXOs say \\u201cthank you.\\u201d Guided by our values of Customer First, Autonomy &amp;amp; Ownership, Agility with Integrity, Transparency, Challenging the status quo and a strong belief that Razorpay grows with Razors,&amp;nbsp; you\\u2019ll be part of a 3000+ strong team building not just products, but the financial infrastructure of the future.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About The Role&lt;/strong&gt;&lt;/p&gt;\\n&lt;p&gt;Ready to architect game-changing payment solutions for Malaysia &amp;amp; Singapore\\u2019s leading enterprises?&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;As a Solution Consultant at Curlec, now part of the dynamic Razorpay group, you&#39;ll spearhead the technical vision and implementation of customized payment strategies. If you&#39;re a tech enthusiast with a knack for problem-solving and a passion for driving innovation in the fintech space, this is your chance to make a significant impact.&lt;/p&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;&lt;strong&gt;Pre-sales Scoping&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Conduct in-depth technical discovery sessions with potential enterprise clients to understand their business objectives and technical landscape.&lt;/li&gt;\\n&lt;li&gt;Develop and present tailored solution proposals, demonstrating the value and technical feasibility of Curlec&#39;s offerings.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;Implementation &amp;amp; Onboarding&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Lead the technical onboarding of enterprise clients, ensuring seamless integration of customized Razorpay\\u2019s payment solutions with their existing systems.&lt;/li&gt;\\n&lt;li&gt;Collaborate with technical teams to oversee the development and configuration of bespoke solutions.&amp;nbsp;&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;Project/Program Management -&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Manage project timelines and act as the primary technical point of contact for enterprise clients throughout the solution delivery process.&lt;/li&gt;\\n&lt;li&gt;Facilitate clear communication between clients, Enterprise Sales, and internal Technical/Product teams.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;Innovation &amp;amp; Optimisation -&amp;nbsp;&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Evaluate Razorpay\\u2019s products against industry trends and client feedback to identify opportunities for innovation and improvement.&lt;/li&gt;\\n&lt;li&gt;Work with the Product team to design and propose new features and solutions aligned with market demands.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;Support &amp;amp; process improvement -&lt;/strong&gt;&amp;nbsp;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Troubleshoot technical issues and collaborate with a global team to ensure timely resolution for enterprise clients.&lt;/li&gt;\\n&lt;li&gt;Identify areas for process optimization and contribute to streamlining internal workflows.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;li&gt;&lt;strong&gt;AI &amp;amp; Productivity Enablement&lt;/strong&gt;&lt;/li&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Leverage AI tools to enhance proposal development, improve client communication, streamline documentation, and support more efficient solutioning during pre-sales and onboarding stages.&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/p&gt;\\n&lt;ol&gt;\\n&lt;li&gt;A minimum of 2-5 years of professional experience, with at least 2 years spent directly engaging with clients in a technical consulting or presales capacity, ideally within the fintech or payments industry.&lt;/li&gt;\\n&lt;li&gt;Deep technical acumen in modern software architectures, including microservices, RESTful APIs, etc&lt;/li&gt;\\n&lt;li&gt;A comprehensive understanding of security best practices, regulatory compliance frameworks relevant to financial services (including PCI DSS), and data privacy principles.&lt;/li&gt;\\n&lt;li&gt;Extensive knowledge of the end-to-end payment lifecycle, tokenization, and familiarity with various payment channels is a huge plus (e.g., cards, e-wallets, FPX).&lt;/li&gt;\\n&lt;li&gt;A proven track record of effectively eliciting and documenting detailed technical requirements from diverse stakeholders and translating them into clear architectural designs and specifications.&lt;/li&gt;\\n&lt;li&gt;Strong analytical and problem-solving abilities, with a proactive mindset to identify and address potential challenges.&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Exceptional communication and presentation skills, with the ability to articulate complex technical concepts clearly and 1&amp;nbsp; concisely to both technical and non-technical audiences.&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Demonstrated ability to work both autonomously and collaboratively within cross-functional teams, managing multiple tasks and deadlines effectively in a fast-paced environment.&lt;/li&gt;\\n&lt;li&gt;Must possess fluency in Malay to effectively engage with local clients and stakeholders.&amp;nbsp;&lt;/li&gt;\\n&lt;li&gt;Strong proficiency in Mandarin is highly desirable due to our diverse client base across Malaysia &amp;amp; Singapore .&lt;/li&gt;\\n&lt;li&gt;Familiarity with AI tools (e.g., ChatGPT or similar) and the ability to use them to enhance presentations, proposals, client communication, and day-to-day productivity.&lt;/li&gt;\\n&lt;/ol&gt;\\n&lt;p&gt;&lt;strong&gt;B&lt;/strong&gt;&lt;strong&gt;enefits&lt;/strong&gt;&lt;/p&gt;\\n&lt;ul&gt;\\n&lt;li&gt;Competitive salary&lt;/li&gt;\\n&lt;li&gt;Large amounts of autonomy and empowerment in your work&lt;/li&gt;\\n&lt;li&gt;Opportunity to join an award winning startup that is now part of the Razorpay group, one of the fastest growing fintech companies in the world&lt;/li&gt;\\n&lt;li&gt;Grow with us. Working in the intersection of Fintech and SaaS, you will have the opportunities to grow in this thriving sector&lt;/li&gt;\\n&lt;/ul&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Location &amp;amp; Commitments&lt;/strong&gt;&lt;/p&gt;\\n&lt;p&gt;Permanent full-time role based at our office in Bangsar South&lt;/p&gt;\\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\\n&lt;p&gt;&lt;strong&gt;Contact us to apply&lt;/strong&gt;&lt;/p&gt;\\n&lt;p&gt;If you&#39;d like to apply for this role, please contact us at hr@curlec.com.&lt;/p&gt;\\n&lt;p&gt;Please attach your CV and tell us why you would be a great fit for our Team.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3a65a3c2-7fff-88ff-9e94-8ab11a050d04&quot;&gt;Razorpay believes in and follows an equal employment opportunity policy that doesn&#39;t discriminate on gender, religion, sexual orientation, colour, nationality, age, etc. We welcome interests and applications from all groups and communities across the globe. &lt;/span&gt;&lt;br&gt;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/div&gt;\\n&lt;div class=&quot;gmail_default&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;&lt;span id=&quot;m_2989597180337834284gmail-m_4972969247898306296gmail-docs-internal-guid-3d0a9248-7fff-a2fd-6fa3-5026f85768d7&quot;&gt;Follow us on &lt;a href=&quot;https://www.linkedin.com/company/razorpay/mycompany/&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://www.linkedin.com/company/razorpay/mycompany/&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0f6sCrv8Ce3IHBvN2Sev8Z&quot;&gt;LinkedIn&lt;/a&gt; &amp;amp; &lt;a href=&quot;https://twitter.com/Razorpay&quot; target=&quot;_blank&quot; data-saferedirecturl=&quot;https://www.google.com/url?q=https://twitter.com/Razorpay&amp;amp;source=gmail&amp;amp;ust=1660290870959000&amp;amp;usg=AOvVaw0ViuP9uutFg1qFCm2nHeh1&quot;&gt;Twitter&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;\", \"departments\": [{\"id\": 4021992005, \"name\": \"Business\", \"child_ids\": [4024743005, 4135081005, 4134248005, 4038759005, 4038484005, 4040706005, 4024737005, 4130660005, 4141485005, 4135090005, 4130661005, 4024739005, 4135159005, 4141487005, 4135162005, 4135164005, 4145118005, 4145123005, 4029702005, 4044868005, 4044878005, 4044879005, 4021999005, 4144767005, 4021993005, 4024744005, 4024750005, 4024751005, 4024758005, 4024757005, 4024763005, 4024764005, 4024776005, 4024779005, 4024782005, 4024793005, 4024785005, 4024791005, 4024800005, 4039244005, 4037907005, 4145107005, 4135155005, 4135082005, 4135083005, 4135084005, 4135089005, 4135085005, 4135086005, 4135088005, 4135087005, 4134249005, 4134250005, 4038760005, 4024792005, 4141486005, 4135156005, 4135157005, 4135158005, 4024740005, 4024741005, 4135161005, 4135160005, 4135163005, 4135165005, 4145119005, 4145120005, 4145121005, 4145122005, 4145125005, 414512