wer generation. The successful candidate will embody Adani’s core values of integrity, innovation, and inclusive growth, fostering a collaborative culture that motivates teams to deliver exceptional performance in a dynamic energy environment.','2026-10-07',NULL,'https://eibd.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/51377','https://eibd.fa.em2.oraclecloud.com/hcmRestApi/resources/latest/recruitingCEJobRequisitions?onlyData=true&finder=findReqs;siteNumber=CX_1&expand=requisitionList&offset=975&limit=25','2026-10-08T06:17:53.503378+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_ORACLE_TALEO)','21ffe3a20d3d443962f75a6118d3ca6869405adb7099cdd694cad0c7a0320b4d','COMP_TOP200_017','https://eibd.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/51377','75e89110088e2156c600160c349d5243',NULL,'{\"id\": \"51377\", \"title\": \"Manager - Mechanical (CHP)\", \"location\": \"Korba, Chhattisgarh, India\", \"dept\": null}','ATS_API_ORACLE_TALEO','2026-10-08 06:19:10.753404',NULL,'2026-10-08 06:21:25.546795',NULL,NULL,'2026-10-08 06:21:25.546795',NULL,'\r\n<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta http-equiv=\"x-ua-compatible\" content=\"ie=edge\">\r\n    <meta http-equiv=\"Content-type\" content=\"text/html; charset=utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, shrink-to-fit=no\">\r\n    <meta name=\"robots\" content=\"index, follow\">\r\n    \r\n\r\n    <!-- Google Tag Manager -->\r\n\r\n    <script nonce=\"9926c7f27c\">\r\n        (function (w, d, s, l, i) {\r\n            w[l] = w[l] || []; w[l].push({\r\n                \'gtm.start\':\r\n\r\n                    new Date().getTime(), event: \'gtm.js\'\r\n            }); var f = d.getElementsByTagName(s)[0],\r\n\r\n                j = d.createElement(s), dl = l != \'dataLayer\' ? \'&l=\' + l : \'\'; j.async = true; j.src =\r\n\r\n                    \'https://www.googletagmanager.com/gtm