 and production, hence to ensure a successful & safe operation in the shop floor as per production plan. The senior engineer also responsible for maintaining, controlling equipment and material movement within the operating scope and as per work instructions / standard operating procedures.','2026-10-05',NULL,'https://eibd.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/55678','https://eibd.fa.em2.oraclecloud.com/hcmRestApi/resources/latest/recruitingCEJobRequisitions?onlyData=true&finder=findReqs;siteNumber=CX_1&expand=requisitionList&offset=975&limit=25','2026-10-08T06:17:53.503378+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_ORACLE_TALEO)','a006133e17267cd6c5d0955d8e5d8b982a4508edf7cd8eb1587be75a013b4d97','COMP_TOP200_017','https://eibd.fa.em2.oraclecloud.com/hcmUI/CandidateExperience/en/sites/CX_1/job/55678','75e89110088e2156c600160c349d5243',NULL,'{\"id\": \"55678\", \"title\": \"Deputy Manager\", \"location\": \"India\", \"dept\": null}','ATS_API_ORACLE_TALEO','2026-10-08 06:19:11.585846',NULL,'2026-10-08 06:21:26.323104',NULL,NULL,'2026-10-08 06:21:26.323104',NULL,'\r\n<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta http-equiv=\"x-ua-compatible\" content=\"ie=edge\">\r\n    <meta http-equiv=\"Content-type\" content=\"text/html; charset=utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, shrink-to-fit=no\">\r\n    <meta name=\"robots\" content=\"index, follow\">\r\n    \r\n\r\n    <!-- Google Tag Manager -->\r\n\r\n    <script nonce=\"9926c7f27c\">\r\n        (function (w, d, s, l, i) {\r\n            w[l] = w[l] || []; w[l].push({\r\n                \'gtm.start\':\r\n\r\n                    new Date().getTime(), event: \'gtm.js\'\r\n            }); var f = d.getElementsByTagName(s)[0],\r\n\r\n                j = d.createElement(s), dl = l != \'dataLayer\' ? \'&l=\' + l : \'\'; j.async = true; j.src =\r\n\r\n                    \'https://www.googletag