b/Kanhe-Dy_-Manager-Warehouse-Operations-Kanh/1436576900','https://jobs.mahindracareers.com/search/?q=&startrow=180','2026-10-13T12:15:12.366094+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','f3da1edb68e3d3bd7292d75ba9279e4a6e649e78eedbf48ebc975c615f9fa66a','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Kanhe-Dy_-Manager-Warehouse-Operations-Kanh/1436576900','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Dy. Manager - Warehouse Operations\", \"location\": \"Kanhe, Kanhe, IN\", \"date\": null, \"function\": null, \"pay_band\": null, \"sections_extracted\": [\"Responsibilities & Key Deliverables\", \"Key Responsibilities\", \"Education Qualification\", \"General Experience\", \"Critical Experience\", \"Key Competencies\", \"Systems/ SAP knowledge\", \"Any Additional Knowledge\", \"System Generated Secondary Skills\"]}','ATS_API_SUCCESSFACTORS','2026-10-12 01:08:12.443738',NULL,'2026-10-13 05:21:22.706425',NULL,NULL,'2026-10-13 05:21:22.706425',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html;charset=UTF-8\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n                        <link type=\"text/css\" class=\"keepscript\" rel=\"stylesheet\" href=\"https://jobs.mahindracareers.com/platform/bootstrap/3.4.8_NES/css/bootstrap.min.css\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/css/j2w/min/bootstrapV3.global.responsive.min.css?h=275f70e9\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/csb/css/navbar-fixed-top.css\" />\n                \n                <script type=\"