careers.com/job/Mumbai-Worli-Senior-Manager-Partnerships-&-Alliances-Mumb/1433773500','https://jobs.mahindracareers.com/search/?q=&startrow=320','2026-10-13T12:15:38.224289+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','72144988ff08e681b4be3428bbb8f8a9a643232282be878d3630c64f4f8d7336','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Mumbai-Worli-Senior-Manager-Partnerships-&-Alliances-Mumb/1433773500','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Senior Manager - Partnerships & Alliances\", \"location\": \"Mumbai - Worli, Mumbai - Worli, IN\", \"date\": null, \"function\": null, \"pay_band\": null, \"sections_extracted\": [\"Responsibilities & Key Deliverables\", \"Experience\", \"Qualifications\", \"General Requirements\", \"Our commitment to Diversity, Equity, and Inclusion\"]}','ATS_API_SUCCESSFACTORS','2026-10-12 01:08:28.136800',NULL,'2026-10-13 05:21:30.363705',NULL,NULL,'2026-10-13 05:21:30.363705',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html;charset=UTF-8\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n                        <link type=\"text/css\" class=\"keepscript\" rel=\"stylesheet\" href=\"https://jobs.mahindracareers.com/platform/bootstrap/3.4.8_NES/css/bootstrap.min.css\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/css/j2w/min/bootstrapV3.global.responsive.min.css?h=275f70e9\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/csb/css/navbar-fixed-top.css\" />\n                \n                <script type=\"text/javascript\" src=\"/platform/js/j