">body{display:none !important;}</style>\n            <script type=\"text/javascript\" id=\"antiClickJackScript\">\n                if (self === top) {\n                    var antiClickjack = document.getElementById(\"antiClickjack\");',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,'SuccessFactors',NULL,NULL,'Mohali',1,'2026-10-13T12:15:40.725017+00:00','1410436800',NULL,NULL,'Prefered : M.Tech\nMechatronics, Instrumentation, Mechanical with 02 years work experience\nOr B.Tech :\nMechatronics, Instrumentation, Mechanical with 03 years work experience.\nJob Segment:\nInstrumentation, Hydraulics, Engineering\nApply Now\nStart apply with LinkedIn\nStart\nPlease wait...',NULL,'We are seeking a highly skilled and experienced professional for the\n4 Poster Test Lab\nto support durability and fatigue testing activities. The candidate will be responsible for operating, maintaining, and troubleshooting servo-hydraulic test systems, executing fatigue test programs, and ensuring accurate data acquisition and reporting.\nFatigue Test Operations',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FETCHED',NULL,NULL,NULL,'\"{\\\"Responsibilities & Key Deliverables\\\": \\\"We are seeking a highly skilled and experienced professional for the\\\\n4 Poster Test Lab\\\\nto support durability and fatigue testing activities. The candidate will be responsible for operating, maintaining, and troubleshooting servo-hydraulic test systems, executing fatigue test programs, and ensuring accurate data acquisition and reporting.\\\\nFatigue Test Operations\\\", \\\"Fatigue Test Operations\\\": \\\"Plan, set up, and execute fatigue and durability tests on vehicle systems, components, and assemblies using 4 Poster Test Rigs.\\\\nDevelop and validate test procedures as per customer, regulatory, and internal requirements.\\\\nMonitor test execution and ensure adherence to defined test cycles, load profiles, and performance criteria.\\\\nAnalyze test results and prepare detailed test reports with observations and recommendations.\\\\nData acquisition and field to lab simulations\\\\nAccelerated testing using data acquisition.\\\\nGenerate Load block cycles from acquired data.\\\", \\\"Experience\\\": \\\"Strain gauging and strain gauge-based data acquisition.\\\\nHands-on experience on data processing tools eg. Siemens Test Lab , Test XPRESS, Ncode, HBK, Somat etc.\\\\nHands-on experience on test controller eg. MOOG, MTS, BIA, Intron (Any One)\\\\nWorking & application knowledge of test instrumentation eg. LVDT, accelerometers, CRO, Thermocouple, Thermistor, Flow meters etc.\\\\nPlease note: Preference is for tractor industry but testing personal from following industries may be considered- Earthmover, Two Wheelers, Cars, Bus & Trucks.\\\\nEducation:\\\", \\\"Education\\\": \\\"Prefered : M.Tech\\\\nMechatronics, Instrumentation, Mechanical with 02 years work experience\\\\nOr B.Tech :\\\\nMechatronics, Instrumentation, Mechanical with 03 years work experience.\\\", \\\"Prefered : M.Tech\\\": \\\"Mechatronics, Instrumentation, Mechanical with 02 years work experience\\\", \\\"Or B.Tech \\\": \\\"Mechatronics, Instrumentation, Mechanical with 03 years work experience.\\\", \\\"Qualifications\\\": \\\"Prefered : M.Tech\\\\nMechatronics, Instrumentation, Mechanical with 02 years work experience\\\\nOr B.Tech :\\\\nMechatronics, Instrumentation, Mechanical with 03 years work experience.\\\\nJob Segment:\\\\nInstrumentation, Hydraulics, Engineering\\\\nApply Now\\\\nStart apply with LinkedIn\\\\nStart\\\\nPlease wait...\\\"}\"',NULL,NULL,'OWNED',NULL,NULL,'2026-10-17 12:30:19.260257','{\"city\": \"Mohali\", \"title\": \"Assistant Manager-R&D\", \"location\": \"Mohali, R&D Mohali, IN\", \"source_url\": \"https://jobs.mahindracareers.com/search/?q=&startrow=480\", \"ats_platform\": \"SuccessFactors\", \"evidence_text\": \"{\\\"title\\\": \\\"Assistant Manager-R&D\\\", \\\"id\\\": \\\"1410436800\\\", \\\"url\\\": \\\"/job/Mohali-Assistant-Manager-R&D-R&D/1410436800/\\\", \\\"location\\\": \\\"Mohali, R&D Mohali, IN\\\"}\", \"detail_fetched\": false, \"application_url\": \"https://jobs.mahindracareers.com/job/Mohali-Assistant-Manager-R&D-R&D/1410436800/\", \"external_job_id\": \"1410436800\", \"detail_fetch_status\": \"NOT_FETCHED\"}','ats_direct_successfactors','DIRECT',NULL,'{\"raw_title\": \"raw_metadata.title\", \"raw_location\": \"location\"}',NULL,'{}',NULL,NULL,NULL,'Mohali, R&D Mohali, IN','Assistant Manager-R&D'),(5452,'JOB_COMP_TOP200_011_ef4180f0bbc2','Deputy Manager - Quality',NULL,NULL,'Kanhe, Kanhe, IN','Kanhe','India',NULL,NULL,NULL,NULL,NULL,NULL,'KEY RESPONSIBILITIES:\nSupport management and continuous improvement of spare parts quality to achieve organizational quality objectives.\nEnsure effective implementation and adherence to Quality processes, Integrated Management Systems (IMS), and The Mahindra Way (TMW) requirements.\nUnderstand key customer needs and contribute to initiatives aimed at enhancing customer experience.\nHandle customer complaints related to spares, including field failures, shortages, and incorrect part supplies.\nPerform root cause analysis using structured problem‑solving tools such as 8D, 5‑Why, and QC Story, and ensure timely and effective closure of issues.\nCoordinate with Operations, Supply Chain, Engineering, and Suppliers to implement corrective and preventive actions (CAPA).\nTrack and analyze customer satisfaction metrics, warranty trends, and field failure data.\nSupport sales return management and effective inventory quality control.\nAssist in handling customer escalations and contribute to improvement in Customer Satisfaction Index (CSI).\nImplement and monitor process audits across the supply chain to ensure compliance and process effectiveness.\nDrive reduction of internal rejections, rework, and scrap related to spares.\nSupport supplier quality management and contribute towards achieving VPPM targets.\nParticipate in and drive continuous improvement initiatives including Kaizen, Yellow Belt / Green Belt projects, and QMS activities.\nEnsure compliance with and continual improvement aligned to ISO 9001:2015, ISO 14001:2015, ISO 45001, and TMW standards.',NULL,NULL,'https://jobs.mahindracareers.com/job/Kanhe-Deputy-Manager-Quality-Kanh/1422820400','https://jobs.mahindracareers.com/search/?q=&startrow=360','2026-10-17T12:30:19.260257+00:00','EXPIRED',0.98,'VERIFIED_HTTP_200',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','553b5a4b4305fd09d00084a4ce86ae31105cbd51fbdf7a10119d17b0109eecc3','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Kanhe-Deputy-Manager-Quality-Kanh/1422820400','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Deputy Manager - Quality\", \"location\": \"Kanhe, Kanhe, IN\", \"date\": null, \"function\": null, \"pay_band\": null, \"sections_extracted\": [\"Responsibilities & Key Deliverables\", \"General Experience\", \"Critical Experience\", \"System Generated Secondary Skills\"]}','ATS_API_SUCCESSFACTORS','2026-10-12 01:08:32.883861',NULL,'2026-10-13 05:21:32.528613',NULL,NULL,'2026-10-17 12:30:19.260257',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html;charset=UTF-8\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n                        <link type=\"text/css\" class=\"keepscript\" rel=\"stylesheet\" href=\"https://jobs.mahindracareers.com/platform/bootstrap/3.4.8_NES/css/bootstrap.min.css\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/css/j2w/min/bootstrapV3.global.responsive.min.css?h=275f70e9\" />\n                            <link type=\"text/css\" rel=\"stylesheet