=\"image/x-icon\" />\n            <style id=\"antiClickjack\" type=\"text/css\">body{display:none !important;}</style>\n            <script type=\"text/javascript\" id=\"antiClickJackScript\">\n                if (self === top) {\n                    var antiClickjack = document.getElementById(\"antiClickjack\");',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,'SuccessFactors',NULL,NULL,'Kanhe',1,'2026-10-13T12:15:42.415610+00:00','1422820400',NULL,NULL,NULL,NULL,'Support management and continuous improvement of spare parts quality to achieve organizational quality objectives.\nEnsure effective implementation and adherence to Quality processes, Integrated Management Systems (IMS), and The Mahindra Way (TMW) requirements.\nUnderstand key customer needs and contribute to initiatives aimed at enhancing customer experience.\nHandle customer complaints related to spares, including field failures, shortages, and incorrect part supplies.\nPerform root cause analysis using structured problem‑solving tools such as 8D, 5‑Why, and QC Story, and ensure timely and effective closure of issues.\nCoordinate with Operations, Supply Chain, Engineering, and Suppliers to implement corrective and preventive actions (CAPA).\nTrack and analyze customer satisfaction metrics, warranty trends, and field failure data.\nSupport sales return management and effective inventory quality control.\nAssist in handling customer escalations and contribute to improvement in Customer Satisfaction Index (CSI).\nImplement and monitor process audits across the supply chain to ensure compliance and process effectiveness.\nDrive reduction of internal rejections, rework, and scrap related to spares.\nSupport supplier quality management and contribute towards achieving VPPM targets.\nParticipate in and drive continuous improvement initiatives including Kaizen, Yellow Belt / Green Belt projects, and QMS activities.\nEnsure compliance with and continual improvement aligned to ISO 9001:2015, ISO 14001:2015, ISO 45001, and TMW standards.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FETCHED',NULL,NULL,NULL,'\"{\\\"Responsibilities & Key Deliverables\\\": \\\"Support management and continuous improvement of spare parts quality to achieve organizational quality objectives.\\\\nEnsure effective implementation and adherence to Quality processes, Integrated Management Systems (IMS), and The Mahindra Way (TMW) requirements.\\\\nUnderstand key customer needs and contribute to initiatives aimed at enhancing customer experience.\\\\nHandle customer complaints related to spares, including field failures, shortages, and incorrect part supplies.\\\\nPerform root cause analysis using structured problem\\\\u2011solving tools such as 8D, 5\\\\u2011Why, and QC Story, and ensure timely and effective closure of issues.\\\\nCoordinate with Operations, Supply Chain, Engineering, and Suppliers to implement corrective and preventive actions (CAPA).\\\\nTrack and analyze customer satisfaction metrics, warranty trends, and field failure data.\\\\nSupport sales return management and effective inventory quality control.\\\\nAssist in handling customer escalations and contribute to improvement in Customer Satisfaction Index (CSI).\\\\nImplement and monitor process audits across the supply chain to ensure compliance and process effectiveness.\\\\nDrive reduction of internal rejections, rework, and scrap related to spares.\\\\nSupport supplier quality management and contribute towards achieving VPPM targets.\\\\nParticipate in and drive continuous improvement initiatives including Kaizen, Yellow Belt / Green Belt projects, and QMS activities.\\\\nEnsure compliance with and continual improvement aligned to ISO 9001:2015, ISO 14001:2015, ISO 45001, and TMW standards.\\\", \\\"General Experience\\\": \\\"Must have more than 8 years of experience in Quality for Manufacturing/ Engineering Industry (Preferably, Automobile Industry)\\\", \\\"Critical Experience\\\": \\\"Knowledge of Complex warehousing process.\\\\nSAP/WM/EWM QM & MM Module.\\\\nSix sigma Green/Black belt.\\\\nCertified lead/internal audit for IMS.\\\\nUnderstanding of engineering drawings.\\\\nBasic understanding of automobile/tractor parts.\\\\nHands on experience on measuring instruments e.g. Vernier Calliper, Micrometre, weighing balance.\\\\nDomain expertise of core quality tools PPAP, APQP, FMEA, SPC & MSA.\\\\nGood English writing skills.\\\\nProficiency in MS office.\\\\nData analysis and reporting skills\\\\nLeadership, communication, and cross\\\\u2011functional coordination\\\", \\\"System Generated Secondary Skills\\\": \\\"Job Segment:\\\\nManufacturing Engineer, Engineer, Engineering, Automotive\\\\nApply Now\\\\nStart apply with LinkedIn\\\\nStart\\\\nPlease wait...\\\"}\"',NULL,NULL,'OWNED',NULL,NULL,'2026-10-17 12:30:19.260257','{\"city\": \"Kanhe\", \"title\": \"Deputy Manager - Quality\", \"location\": \"Kanhe, Kanhe, IN\", \"source_url\": \"https://jobs.mahindracareers.com/search/?q=&startrow=480\", \"ats_platform\": \"SuccessFactors\", \"evidence_text\": \"{\\\"title\\\": \\\"Deputy Manager - Quality\\\", \\\"id\\\": \\\"1422820400\\\", \\\"url\\\": \\\"/job/Kanhe-Deputy-Manager-Quality-Kanh/1422820400/\\\", \\\"location\\\": \\\"Kanhe, Kanhe, IN\\\"}\", \"detail_fetched\": false, \"application_url\": \"https://jobs.mahindracareers.com/job/Kanhe-Deputy-Manager-Quality-Kanh/1422820400/\", \"external_job_id\": \"1422820400\", \"detail_fetch_status\": \"NOT_FETCHED\"}','ats_direct_successfactors','DIRECT',NULL,'{\"raw_title\": \"raw_metadata.title\", \"raw_location\": \"location\"}',NULL,'{}',NULL,NULL,NULL,'Kanhe, Kanhe, IN','Deputy Manager - Quality'),(5453,'JOB_COMP_TOP200_011_726c3a23e266','Senior Engineer- VES',NULL,NULL,'Chennai, Chennai-MRV-AD, IN','Chennai-MRV-AD','India',NULL,NULL,NULL,NULL,NULL,NULL,'KEY RESPONSIBILITIES:\nTo design, develop and implement Lighting System - Exterior & Interior\nBenchmarking of lighting technologies\nPOC, SOR, DVP