      <style id=\"antiClickjack\" type=\"text/css\">body{display:none !important;}</style>\n            <script type=\"text/javascript\" id=\"antiClickJackScript\">\n                if (self === top) {\n                    var antiClickjack = document.getElementById(\"antiClickjack\");',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,'SuccessFactors',NULL,NULL,'Nagpur',1,'2026-10-13T12:15:59.661591+00:00','1422513200',NULL,NULL,'B.E./B.Tech Electrical Engineering\nJob Segment:\nElectrical Engineering, Manufacturing Engineer, Electrical, Welding, Engineering, Manufacturing, Automotive\nApply Now\nStart apply with LinkedIn\nStart\nPlease wait...',NULL,'Purpose of the role:\nTo support planning, execution, commissioning, operation and maintenance of electrical infrastructure and utilities for Body Shop to ensure project readiness during Greenfield development and reliable power availability, safety and operational excellence post SOP.\nRoles and responsibilities:\nGreenfield Project Phase\nSupport execution and monitoring of electrical infrastructure activities for Body Shop, including HT/LT distribution systems, substations, transformers, DG sets, UPS systems, MCCs, PCCs, cable routing and utility power distribution networks as per project schedules and quality requirements.\nCoordinate installation, testing and commissioning of electrical systems and utility infrastructure to ensure readiness for robotic welding lines, conveyors, fixtures, automation systems, equipment installation, trials and Start of Production (SOP).\nWork closely with Electrical, Mechanical, Production, Manufacturing Engineering and contractor teams to ensure timely completion of project activities, commissioning support and closure of punch points.\nEnsure compliance with approved drawings, technical specifications, electrical standards, statutory requirements and safety regulations during project execution and commissioning activities.\nOperations & Facility Management Phase\nSupport preventive and breakdown maintenance of substations, transformers, DG sets, MCCs, PCCs, UPS systems, welding power systems, lighting systems and electrical distribution networks to ensure uninterrupted Body Shop operations.\nMonitor power consumption, equipment health, electrical system performance and utility reliability, and support implementation of energy management and continuous improvement initiatives.\nCoordinate contractor activities, verify work completion and ensure adherence to quality, safety and delivery requirements for maintenance and project works.\nMaintain maintenance records, electrical asset history, statutory inspection records and MIS reports, while supporting expansion projects, infrastructure upgrades, automation enhancements and electrical safety compliance activities.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FETCHED',NULL,NULL,NULL,'\"{\\\"Responsibilities & Key Deliverables\\\": \\\"Purpose of the role:\\\\nTo support planning, execution, commissioning, operation and maintenance of electrical infrastructure and utilities for Body Shop to ensure project readiness during Greenfield development and reliable power availability, safety and operational excellence post SOP.\\\\nRoles and responsibilities:\\\\nGreenfield Project Phase\\\\nSupport execution and monitoring of electrical infrastructure activities for Body Shop, including HT/LT distribution systems, substations, transformers, DG sets, UPS systems, MCCs, PCCs, cable routing and utility power distribution networks as per project schedules and quality requirements.\\\\nCoordinate installation, testing and commissioning of electrical systems and utility infrastructure to ensure readiness for robotic welding lines, conveyors, fixtures, automation systems, equipment installation, trials and Start of Production (SOP).\\\\nWork closely with Electrical, Mechanical, Production, Manufacturing Engineering and contractor teams to ensure timely completion of project activities, commissioning support and closure of punch points.\\\\nEnsure compliance with approved drawings, technical specifications, electrical standards, statutory requirements and safety regulations during project execution and commissioning activities.\\\\nOperations & Facility Management Phase\\\\nSupport preventive and breakdown maintenance of substations, transformers, DG sets, MCCs, PCCs, UPS systems, welding power systems, lighting systems and electrical distribution networks to ensure uninterrupted Body Shop operations.\\\\nMonitor power consumption, equipment health, electrical system performance and utility reliability, and support implementation of energy management and continuous improvement initiatives.\\\\nCoordinate contractor activities, verify work completion and ensure adherence to quality, safety and delivery requirements for maintenance and project works.\\\\nMaintain maintenance records, electrical asset history, statutory inspection records and MIS reports, while supporting expansion projects, infrastructure upgrades, automation enhancements and electrical safety compliance activities.\\\", \\\"Experience\\\": \\\"5+ years in electrical utilities, infrastructure \\\\u00a0with exposure to Greenfield automotive projects. Body Shop projects, robotic welding lines, power distribution and automation infrastructure\\\", \\\"Industry Preferred\\\": \\\"Automobile, Auto Components, Heavy Engineering, Industrial Manufacturing\\\", \\\"Qualifications\\\": \\\"B.E./B.Tech Electrical Engineering\\\\nJob Segment:\\\\nElectrical Engineering, Manufacturing Engineer, Electrical, Welding, Engineering, Manufacturing, Automotive\\\\nApply Now\\\\nStart apply with LinkedIn\\\\nStart\\\\nPlease wait...\\\"}\"',NULL,NULL,'OWNED',NULL,NULL,'2026-10-17 12:30:19.260257','{\"city\": \"Nagpur\", \"title\": \"Dy. Manager - Building, Utilities & Other Infra for Body Shop (Electrical)\", \"location\": \"Nagpur, Nagpur, IN\", \"source_url\": \"https://jobs.mahindracareers.com/search/?q=&startrow=520\", \"ats_platform\": \"SuccessFactors\", \"evidence_text\": \"{\\\"title\\\": \\\"Dy. Manager - Building, Utilities & Other Infra for Body Shop (Electrical)\\\", \\\"id\\\": \\\"1422513200\\\", \\\"url\\\": \\\"/job/Nagpur-Dy_-Manager-Building%2C-Utilities-&-Other-Infra-for-Body-Shop-%28Electrical%29-Nagp/1422513200/\\\", \\\"location\\\": \\\"Nagpur, Nagpur, IN\\\"}\", \"detail_fetched\": false, \"application_url\": \"https://jobs.mahindracareers.com/job/Nagpur-Dy_-Manager-Building%2C-Utilities-&-Other-Infra-for-Body-Shop-%28Electrical%29-Nagp/1422513200/\", \"external_job_id\": \"1422513200\", \"detail_fetch_status\": \"NOT_FETCHED\"}','ats_direct_successfactors','DIRECT',NULL,'{\"raw_title\": \"raw_metadata.title\", \"raw_location\": \"location\"}',NULL,'{}',NULL,NULL,NULL,'Nagpur, Nagpur, IN','Dy. Manager - Building, Utilities & Other Infra for Body Shop (Electrical)'),(5469,'JOB_COMP_TOP200_011_720b6b1f866c','Deputy Manager - Process Engineering',NULL,NULL,'Chakan, Chakan, IN','Chakan','India',NULL,NULL,NULL,NULL,NULL,NULL,'KEY RESPONSIBILITIES:\nFormability Analysis of Sheet Metal Parts.\nSimulation with CAE Software ( Auto Form / Pam Stamp). Suggesting Counter measures for the Defects.\nInteraction with customer and Concern Resolution. Manufacturing feasibility study for new model introduction in existing line.\nDevelop BIW process plans for Manual and Robotic welding Lines.\nDevelop BIW Robotic welding simulation cells and OLP in PS Team center / standalone.\nGenerate standards and check sheets for Simulation and OLP through benchmarking and lessons learnt.\nCollaborate with CME process, PLC and Line builders for verification of Simulation and OLP during DAP and trials at suppliers.\nInstallation and commissioning with post SOP support for Process and cycle time prove out.\nLine layout, Manufacturing process flow, Cycle time chart and RFQ preparation of BIW sub assembly.\nDo process study wrt gun, equipment, fixtures and suggest suitable changes in product to ensure first time right manufacturability.\nBuild up the station/cell/line in PS by adding all relevant resources.\nCheck for Gun reachability, apply all kinematics to relevant tools and create robot path with zero collision with basic tools.\nGenerate Basic path (welding, tip dressing, etc) and zoning conditions to avoid any collision.\nCollaborate and Coordinate with Line builders to get the line simulation done and optimize the robot paths, robot zoning and again give feedback for any improvement required in design.\nHands on experience of virtual controller such as- ABB / Fanuc / KUKA etc, generate the OLP with the cycle time accuracy of 99%.\nFind out root causes to achieve cycle time targets if not achieved.\nEnsure Zero error / collision / losses through continuous involvement with execution team.',NULL,NULL,'https://jobs.mahindracareers.com/job/Chakan-Deputy-Manager-Process-Engineering-Chak/1432369600','https://jobs.mahindracareers.com/search/?q=&startrow=440','2026-10-13T12:16:00.755795+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','2482e070a7336e990e9e7d79690c157f070813c94258ca726f9470605b86244b','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Chakan-Deputy-Manager-Process-Engineering-Chak/1432369600','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Deputy Manager - Process Engineering\", \"location\": \"Chakan, Chakan, IN\", \"date\": null, \"function\": null, \"pay_band\": null, \"sections_extracted\": [\"Responsibilities & Key Deliverables\", \"Education Qualification\", \"General Experience\"]}','ATS_API_SUCCESSFACTORS','2026-10-12 01:08:40.700499',NULL,'2026-10-13 05:21:37.349748',NULL,NULL,'2026-10-13 05:21:37.349748',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" con