                          <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/fontawesome4.7/css/font-awesome-4.7.0.min.css?h=275f70e9\" />\n<style>\nbody > .modal-backdrop {\n    display: none !important;\n}\n.menu.desktop .nav > li .dropdown-menu li a{ color : white !important}\n#header .links a{ color: white !important;}\n.dropdown-menu.company-dropdown.headerdropdown.backgroundcolordc8b140b5a119dc3 .menu{ color : black !important}\n.custom-header-menu .nav.nav-pills{ width: 807px !important; }\n.custom-header-signinLanguage .inner.limitwidth{ max-width: 1200px; }\n.customPlugin{ margin-bottom: 0 !important; }\n\n</style>\n<script type=\"text/javascript\"></script></body>\n\n        \n        <link rel=\"shortcut icon\" href=\"//rmkcdn.successfactors.com/1bf0fd1f/9349339a-5cfe-46bb-98d8-3.png\" type=\"image/x-icon\" />\n            <style id=\"antiClickjack\" type=\"text/css\">body{display:none !important;}</style>\n            <script type=\"text/javascript\" id=\"antiClickJackScript\">\n                if (self === top) {\n                    var antiClickjack = document.getElementById(\"antiClickjack\");',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,'SuccessFactors',NULL,NULL,'Mumbai A.O',1,'2026-10-13T10:46:22.237111+00:00','1439406900',NULL,NULL,'Strong expertise in React\nStrong expertise in Node.js\nStrong experience in Python\nSolid working knowledge of SQL and relational database design\nExperience building and consuming REST APIs\nAbility to write clean, scalable, and maintainable code\nExperience with GCP cloud environment and deployment pipelines\nStrong problem-solving, debugging, and communication skills',NULL,'Design, develop, and maintain robust web applications using React for dynamic, responsive, and user-friendly interfaces\nBuild and optimize backend services and APIs using Node.js to support enterprise business workflows and integrations\nImplement data processing, automation, and application logic using Python\nWork with SQL databases to design efficient schemas, write complex queries, and optimize performance\nCollaborate with cross-functional teams including product managers, engineering leads, architects, and QA to deliver solutions aligned with business goals\nDrive best practices in software design, code quality, testing, performance tuning, and security\nLead technical discussions, provide architectural guidance, and contribute to engineering standards\nTroubleshoot production issues and provide effective, timely resolutions\nMentor junior developers and support team growth through code reviews and technical knowledge sharing',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FETCHED',NULL,NULL,NULL,'\"{\\\"Responsibilities & Key Deliverables\\\": \\\"We are looking for a Senior Full Stack Developer with 5+ years of hands-on experience to build and deliver scalable, high-quality enterprise applications. The ideal candidate will have deep expertise in frontend and backend development, with a strong focus on performance, maintainability, and business impact.\\\\nKey Responsibilities\\\", \\\"Key Responsibilities\\\": \\\"Design, develop, and maintain robust web applications using React for dynamic, responsive, and user-friendly interfaces\\\\nBuild and optimize backend services and APIs using Node.js to support enterprise business workflows and integrations\\\\nImplement data processing, automation, and application logic using Python\\\\nWork with SQL databases to design efficient schemas, write complex queries, and optimize performance\\\\nCollaborate with cross-functional teams including product managers, engineering leads, architects, and QA to deliver solutions aligned with business goals\\\\nDrive best practices in software design, code quality, testing, performance tuning, and security\\\\nLead technical discussions, provide architectural guidance, and contribute to engineering standards\\\\nTroubleshoot production issues and provide effective, timely resolutions\\\\nMentor junior developers and support team growth through code reviews and technical knowledge sharing\\\", \\\"Experience\\\": \\\"5+ yrs.\\\", \\\"Qualifications\\\": \\\"Bachelor\\\\u2019s degree in Computer Science, Engineering, or a related field, or equivalent work experience\\\\nExperience with cloud platforms such as AWS, Azure, or GCP\\\\nKnowledge of CI/CD pipelines and DevOps practices\\\\nExperience with testing frameworks and automated quality checks\\\\nFamiliarity with microservices or modular application design\\\\nExposure to enterprise application architecture and security standards\\\", \\\"General Requirements\\\": \\\"Strong expertise in React\\\\nStrong expertise in Node.js\\\\nStrong experience in Python\\\\nSolid working knowledge of SQL and relational database design\\\\nExperience building and consuming REST APIs\\\\nAbility to write clean, scalable, and maintainable code\\\\nExperience with GCP cloud environment and deployment pipelines\\\\nStrong problem-solving, debugging, and communication skills\\\", \\\"Our commitment to Diversity, Equity, and Inclusion\\\": \\\"Job Segment:\\\\nEngineer, Engineering\\\\nApply Now\\\\nStart apply with LinkedIn\\\\nStart\\\\nPlease wait...\\\"}\"',NULL,NULL,'OWNED',NULL,NULL,NULL,'{}','ats_direct_successfactors','DIRECT',NULL,'{\"raw_title\": \"job_title\", \"raw_location\": \"location\"}',NULL,'{}',NULL,NULL,NULL,'Mumbai A.O, MUM-KND-AFS(AD), IN','Senior Product Engineer - BI Platform');
INSERT INTO `admin_panel_job` VALUES (5839,'JOB_COMP_TOP200_011_2839454ad5cd','Deputy Manager - BIW (AD CDMM)',NULL,NULL,'Chennai, Chennai-MRV, IN','Chennai-MRV','India',NULL,NULL,NULL,NULL,NULL,NULL,'Responsibilities & Key Deliverables\nDescription of the job and key result areas:\nÂ Accountable for Delivery of all DE with respect to the allotted platforms.\nÂ Ensure that the respective DE Officers are delivering on the TCP (Time, Cost, and Performance) requirements of Platforms.\nÂ Draw up a plan to develop/procure components with vendors within time, cost and quality objectives\nÂ Vendor analysis and rationalization for capacity assessment, time frame agreement\nÂ To ensure the material and tooling cost are settled within the budgeted values\nÂ To support pricing cell in cost estimation activities component wise and details costing of the components/new part\nÂ Effective co-ordination with the Design team to ensure first time right and end delivery of product\nÂ Variance analysis at each stage of development in terms of Quality, Cost and Delivery and corrective action\nÂ Developing and implementing innovative approaches in cost reduction\nÂ To assess / negotiate investments involved for toolingÂs / vendor aid requirement for components development\nÂ To support the pricing cell in selection of vendor as per guiding policy for the part\nÂ To meet MRD (Material Receipt Date) targets\nÂ To meet the Gateways as per MPDS (Mahindra Product Development System) targets for projects.\nÂ To get actively involved in project feasibility studies\nÂ Responsible for quality, Cost and delivery (QCD) targets for all new products and improvements in existing products\nÂ Support STA counterpart in part development as per APQP process and Project timelines\nKnowledge/Skills Required:\n- PPAP, New Part Development System (MP, EP, VP, PP), APQP, SPC, and Problem-solving techniques\n- Zero base costing\n- Price negotiation\n- GD and T knowledge\n- Hands on experience on SAP MM module\n- MS Office Knowledge (Word, Excel, PowerPoint)\n- Commercial knowledge on various taxation and Inco terms\nExperience\n8-10 years\nIndustry Preferred\nOEM\nQualifications\nBE\nGeneral Requirements\nOur commitment to Diversity, Equity, and Inclusion\nAt Mahindra and Mahindra Limited, we believe that diversity drives innovation, and inclusion is at the heart of everything we do. We are committed to cultivating a workplace where every individual feels valued, respected, and empowered to thrive.\nWe are proud to be an Equal Opportunity Employer. All qualified applicants will be considered for employment without regard to age, caste, race, religion, color, ethnic origin, gender identity, nationality, physical or mental disability, medical condition, sexual orientation, educational background, marital or domestic partnership status, pregnancy or childbirth, veteran status, citizenship status, ancestry, financial status, or any other personal characteristic protected by applicable law.\nWe actively encourage candidates from all backgrounds to apply and bring their unique perspectives to our teams. We are committed to ensuring an accessible and inclusive experience for all applicants.\nTogether, we rise by embracing differences and building a future that reflects the communities we serve.',NULL,NULL,'https://jobs.mahindracareers.com/job/Chennai-Deputy-Manager-BIW-%28AD-CDMM%29-Chen/1439406500','https://jobs.mahindracareers.com/search/?q=&startrow=20','2026-10-13T10:46:22.237111+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','7cc7c0800b88eacb46252b51402b2ea9c98683bac43eed13d703167da4dce692','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Chennai-Deputy-Manager-BIW-%28AD-CDMM%29-Chen/1439406500','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Deputy Manager - BIW (AD CDMM)\", \"location\": \"Chennai, Chennai-MRV, IN\", \"external_id\": \"1439406500\", \"raw_evidence\": \"{\\\"title\\\": \\\"Deputy Manager - BIW (AD CDMM)\\\", \\\"id\\\": \\\"1439406500\\\", \\\"url\\\": \\\"/job/Chennai-Deputy-Manager-BIW-%28AD-CDMM%29-Chen/1439406500/\\\", \\\"location\\\": \\\"Chennai, Chennai-MRV, IN\\\"}\"}','ATS_API_SUCCESSFACTORS','2026-10-13 05:21:01.960831',NULL,'2026-10-13 05:21:01.959314',NULL,NULL,'2026-10-13 05:21:01.959314',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html;charset=UTF-8\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n                        <link type=\"text/css\" class=\"keepscript\" rel=\"stylesheet\" href=\"https://jobs.mahindracareers.com/platform/bootstrap/3.4.8_NES/css/bootstrap.min.css\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/css/j2w/min/bootstrapV3.global.responsive.min.css?h=275f70e9\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/csb/css/navbar-fixed-top.css\" />\n                \n                <script type=\"text/javascript\" src=\"/platform/js/j2w/j2w.fallbacks.js\"></script>\n                \n                \n                <script type=\"text/javascript\" src=\"https://performancemanager4.successfactors.com/verp/vmod_v1/ui/extlib/jquery_3.5.1/jquery.js\" onerror=\"loadFallbacks(\'/platform/js/jquery/jquery-3.5.1.min.js\', \'/platform/js/jquery/jquery-migrate-3.1.0.min.js\')\"></script>\n                <script type=\"text/javascript\" src=\"https://performancemanager4.successfactors.com/verp/vmod_v1/ui/extlib/jquery_3.5.1/jquery-migrate.js\"></script>\n            <script type=\"text/javascript\" src=\"/platform/js/jquery/jquery-migrate-1.4.1.js\"></script>\n            <title>Mah