s\n:\nExpert in Sheet metal, plastic and Rubber part design and development.\nExpertise in UG- NX software and surface modelling.',NULL,NULL,'https://jobs.mahindracareers.com/job/Chennai-Engineer-Body-Integrated-Systems-Chen/1439166400','https://jobs.mahindracareers.com/search/?q=&startrow=60','2026-10-13T10:46:22.237111+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','3dede2cb27c201b9178bdce83f7333f1ff8d77c2da8e78a2eef998b39fbb18c6','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Chennai-Engineer-Body-Integrated-Systems-Chen/1439166400','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Engineer - Body Integrated Systems\", \"location\": \"Chennai, Chennai-MRV(FD), IN\", \"external_id\": \"1439166400\", \"raw_evidence\": \"{\\\"title\\\": \\\"Engineer - Body Integrated Systems\\\", \\\"id\\\": \\\"1439166400\\\", \\\"url\\\": \\\"/job/Chennai-Engineer-Body-Integrated-Systems-Chen/1439166400/\\\", \\\"location\\\": \\\"Chennai, Chennai-MRV(FD), IN\\\"}\"}','ATS_API_SUCCESSFACTORS','2026-10-13 05:21:07.044408',NULL,'2026-10-13 05:21:07.040803',NULL,NULL,'2026-10-13 05:21:07.040803',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html;charset=UTF-8\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n                        <link type=\"text/css\" class=\"keepscript\" rel=\"stylesheet\" href=\"https://jobs.mahindracareers.com/platform/bootstrap/3.4.8_NES/css/bootstrap.min.css\" />\n                            <link type=\"text/css\" rel=\"stylesheet\" href=\"/platform/css/j2w/min/bootstrapV3.global.responsive.min.css?h=275f70e9\" />\n                            <link typ