          var antiClickjack = document.getElementById(\"antiClickjack\");',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,'SuccessFactors',NULL,NULL,'Chennai',1,'2026-10-13T12:16:37.218537+00:00','1423347500',NULL,NULL,NULL,NULL,'The role requires a deep understanding of various communication protocols (CAN, TCP/IP, HTTP, MQTT, LIN, UART) and embedded architectures.\nTelematics Protocol Expertise\n: Hands-on experience with serial protocols, CAN analysis (vector-canoe, CANalyzer), and CAN simulation tools.\nSoftware Testing\n: Proficiency in integration, black-box, sanity, smoke, unit testing, and validation of software APIs.\nDefect & Log Analysis\n: Identify defects, generate reports, and perform log analysis for debugging.\nNetwork Simulators\n: Knowledge of 2G, 3G, 4G simulators is advantageous.\nCellular Protocols\n: Familiarity with 5G, LTE, UMTS, GSM, and location-based technologies is a plus.\nSystem Knowledge\n: Strong understanding of hardware systems, I/Os, and debugging processes.\nCloud & Security\n: Exposure to cloud technologies, product security methods, and connectivity trends.\nMobile & ECU Testing\n: Experience with mobile app testing and automotive ECUs from a telematics perspective.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FETCHED',NULL,NULL,NULL,'\"{\\\"Responsibilities & Key Deliverables\\\": \\\"The role requires a deep understanding of various communication protocols (CAN, TCP/IP, HTTP, MQTT, LIN, UART) and embedded architectures.\\\\nTelematics Protocol Expertise\\\\n: Hands-on experience with serial protocols, CAN analysis (vector-canoe, CANalyzer), and CAN simulation tools.\\\\nSoftware Testing\\\\n: Proficiency in integration, black-box, sanity, smoke, unit testing, and validation of software APIs.\\\\nDefect & Log Analysis\\\\n: Identify defects, generate reports, and perform log analysis for debugging.\\\\nNetwork Simulators\\\\n: Knowledge of 2G, 3G, 4G simulators is advantageous.\\\\nCellular Protocols\\\\n: Familiarity with 5G, LTE, UMTS, GSM, and location-based technologies is a plus.\\\\nSystem Knowledge\\\\n: Strong understanding of hardware systems, I/Os, and debugging processes.\\\\nCloud & Security\\\\n: Exposure to cloud technologies, product security methods, and connectivity trends.\\\\nMobile & ECU Testing\\\\n: Experience with mobile app testing and automotive ECUs from a telematics perspective.\\\", \\\"Experience\\\": \\\"5-8 Years\\\", \\\"Our commitment to Diversity, Equity, and Inclusion\\\": \\\"Job Segment:\\\\nElectronics Engineer, Electrical Engineering, Engineering Manager, Electrical, Engineering, Automotive\\\\nApply Now\\\\nStart apply with LinkedIn\\\\nStart\\\\nPlease wait...\\\"}\"',NULL,NULL,'OWNED',NULL,NULL,'2026-10-17 12:30:19.260257','{\"city\": \"Chennai\", \"title\": \"Lead Engineer-Electrical & Electronics\", \"location\": \"Chennai, Chennai-MRV-AD, IN\", \"source_url\": \"https://jobs.mahindracareers.com/search/?q=&startrow=460\", \"ats_platform\": \"SuccessFactors\", \"evidence_text\": \"{\\\"title\\\": \\\"Lead Engineer-Electrical & Electronics\\\", \\\"id\\\": \\\"1423347500\\\", \\\"url\\\": \\\"/job/Chennai-Lead-Engineer-Electrical-&-Electronics-Chen/1423347500/\\\", \\\"location\\\": \\\"Chennai, Chennai-MRV-AD, IN\\\"}\", \"detail_fetched\": false, \"application_url\": \"https://jobs.mahindracareers.com/job/Chennai-Lead-Engineer-Electrical-&-Electronics-Chen/1423347500/\", \"external_job_id\": \"1423347500\", \"detail_fetch_status\": \"NOT_FETCHED\"}','ats_direct_successfactors','DIRECT',NULL,'{\"raw_title\": \"raw_metadata.title\", \"raw_location\": \"location\"}',NULL,'{}',NULL,NULL,NULL,'Chennai, Chennai-MRV-AD, IN','Lead Engineer-Electrical & Electronics'),(5902,'JOB_COMP_TOP200_011_bb8e0c884e0c','Deputy Manager - System Architecture',NULL,NULL,'Bangalore, Banglore CO, IN','Banglore CO','India',NULL,NULL,NULL,NULL,NULL,NULL,'KEY RESPONSIBILITIES:\nExpertise in Architecting and designing system functions for Electric Vehicle Powertrains:\n1) Identify, Analyse and synthesize all the stakeholder’s needs, Vehicle Requirements (VRS), Service requirements, Homologation requirements, Customer, System Design requirements (SDS)\n2) Designs the system architecture of various vehicle level functions, entry and exit criteria at system level interfacing to Software and Hardware\n3) Drive System Architecture design discussions with EV Module teams including embedded software and hardware teams\n4) Able to create Block Diagram, Flow charts, State Diagrams, Sequence Diagrams and timing diagrams for a function\n5) Lead any new technology/ new function discussion and adopt the same into system architecture\n6) Be the focal point for any change requirements and assess the impact on the vehicle architecture/design/performance/etc\n7) Drive in-depth technical discussions on the areas of system architecture of electric powertrain\n8) Able to create System degradation strategies applicable to EV domain\n9) Thorough Knowledge on Automotive Communication Networks CAN, LIN, Ethernet\n10) Hands on experience on ALM Polarian, CANOE, Canalyzer, CAN db++ editor, Matlab/ Simulink and Diagnostic tools\n11) Ability to Debug ongoing field concerns and provide relevant solution on the Requirement and Architecture level',NULL,NULL,'https://jobs.mahindracareers.com/job/Bangalore-Deputy-Manager-System-Architecture-Bang/1433297800','https://jobs.mahindracareers.com/search/?q=&startrow=360','2026-10-17T12:30:19.260257+00:00','EXPIRED',0.98,'VERIFIED_HTTP_200',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','ffac8cb2a6843c97ac88d3dcfb124f7ed69060c9e55bf9c1483232e0f84cfa4e','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Bangalore-Deputy-Manager-System-Architecture-Bang/1433297800','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Deputy Manager - System Architecture\", \"location\": \"Bangalore, Banglore CO, IN\", \"date\": null, \"function\": null, \"pay_band\": null, \"sections_extracted\": [\"Responsibi