cript\">\n                if (self === top) {\n                    var antiClickjack = document.getElementById(\"antiClickjack\");',NULL,'All populated fields verified against raw source evidence.','STALE',NULL,'SuccessFactors',NULL,NULL,'Chennai',1,'2026-10-13T12:16:40.540540+00:00','1432843300',NULL,NULL,'\'Lighting Engineering\n- Deep knowledge and expertise in lighting technologies: Halogen, LED, MFR, Light Guides, Light Blades, Projection systems, adaptive, matrix systems.\n- Lighting Electronics: deep knowledge of driver circuits, control modules, sensors, microcontrollers, LED selection/binning, thermal derating, PCBs, ESD/EMI design and integration with vehicle electrical architecture (CAN/LIN/Ethernet communication, diagnostics, software calibration & EOL test strategies.).\n- Knowledge of optical design -  reflector/projector, light guides, micro‑optics, photometry (luminous flux, intensity, distributions), glare control\n- Knowledge of Thermal & Mechanical design : CFD for heat dissipation, heat sink design, material selection, sealing/venting, vibration and durability.\n- Knowledge of Standards: AIS/BIS, UNECE & FMVSS/SAE standards.\nMethods & Tools\n- Familiarity in CAD tools: CATIA V5/V6; GD&T, tolerance analysis.\n- Familiarity in CAE analysis tools: thermal simulation, basic optical simulation exposure (Ansys Speos, Lucid).\n- Quality: DFMEA/PFMEA, PPAP, Control Plans.\n- Program tools: PLM (Teamcenter, 3DX), requirements management, Jira/MS Project, dashboards.\nManufacturing & Industrialization\n- Injection moulding (optical‑grade lenses, surface quality/flow), coating & metallization (aluminium vacuum metallization).\n- Welding techniques - Laser welding, ultrasonic welding & Hotplate Welding. Sealing/venting processes, potting, conformal coating, PCB assembly.\n- Assembly line design, EOL optical & leakage tests, poka‑yoke.',NULL,'\'Product Ownership & Road mapping\n- Lead the Lighting System\'s Engineering function for assigned vehicle platforms - Own lighting product strategy for assigned platform(s): technology roadmap (LED/micro‑LED, adaptive/matrix, projection, dynamic animations, light signatures), cost, weight, sustainability, and serviceability.\n- Define system architecture (electro‑optical, thermal, mechanical, sealing, EMC/EMI, diagnostics) and interface control (CAN/LIN, power, thermal paths, package space, styling surfaces).\n- Mentor the engineering team fostering innovation and accountability\nDesign & Development\n- Lead the end-to-end product lifecycle for lighting systems – concept, design, validation, industrialization, and launch.\n- Lead concept freeze, package studies, and feasibility with Styling/Vehicle Architecture.\n- Direct detailed design (optics, PCB, heat sinks, lenses, housings, gaskets, vents, brackets) in CATIA, ensuring DfX (DfM/DfA/DfS), tolerance stack‑ups, VA/VE, and design robustness.\n- Oversee photometry & other performance compliance; define target light distributions, performance margins, and derating strategies.\nValidation & Homologation\n- Ensure compliance with global automotive standards (AIS, ECE, SAE, FMVSS).\n- Develop and execute DVP&R for environmental, optical, electrical, EMC/EMI, durability, corrosion, vibration, sealing, thermal and vehicle‑level integration (CAN/LIN comms, diagnostics).\n- Ensure global regulatory compliance (e.g., UNECE, AIS/BIS, SAE/ISO etc.)\nQuality & Risk\n- Drive APQP/PPAP, DFMEA/PFMEA, Control Plan, and 8D resolution; ensure lessons learned reuse and robust problem prevention.\n- Champion traceability for critical components (LED binning, lens material lots, PCB revisions).\nSupplier & Sourcing Leadership\n- Manage supplier partnerships to achieve cost, quality, and delivery targets.\n- Manage Tier‑1/Tier‑2 suppliers; negotiate technology, cost, and timing; define SOW and acceptance criteria.\n- Conduct design reviews, audits, and process capability checks; support tooling and gauge development.\nProgram & Cross‑Functional Leadership\n- Own timelines, budgets, and BOM for lighting commodities; manage EBOM/MBOM alignment.\n- Collaborate with Manufacturing Engineering for line readiness, PFMEA, jigs/fixtures, EOL testing.\n- Interface with After‑Sales for service parts strategy, diagnostics, and repairability.\nInnovation & IP\n- Drive innovation in lighting technologies (LED, Light Projection, OLED, laser, adaptive Lighting, matrix Lighting, smart lighting).\n- Incubate new features (Welcome/Goodbye animations, ADB/Matrix, logo projection, adaptive signatures, OTA‑capable diagnostics) and file patents/IP where applicable.\nSustainability & Compliance\n- Embed recyclability and drive weight and cost reduction.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'FETCHED',NULL,NULL,NULL,'\"{\\\"Responsibilities & Key Deliverables\\\": \\\"\'Product Ownership & Road mapping\\\\n- Lead the Lighting System\'s Engineering function for assigned vehicle platforms - Own lighting product strategy for assigned platform(s): technology roadmap (LED/micro\\\\u2011LED, adaptive/matrix, projection, dynamic animations, light signatures), cost, weight, sustainability, and serviceability.\\\\n- Define system architecture (electro\\\\u2011optical, thermal, mechanical, sealing, EMC/EMI, diagnostics) and interface control (CAN/LIN, power, thermal paths, package space, styling surfaces).\\\\n- Mentor the engineering team fostering innovation and accountability\\\\nDesign & Development\\\\n- Lead the end-to-end product lifecycle for lighting systems \\\\u2013 concept, design, validation, industrialization, and launch.\\\\n- Lead concept freeze, package studies, and feasibility with Styling/Vehicle Architecture.\\\\n- Direct detailed design (optics, PCB, heat sinks, lenses, housings, gaskets, vents, brackets) in CATIA, ensuring DfX (DfM/DfA/DfS), tolerance stack\\\\u2011ups, VA/VE, and design robustness.\\\\n- Oversee photometry & other performance compliance; define target light distributions, performance margins, and derating strategies.\\\\nValidation & Homologation\\\\n- Ensure compliance with global automotive standards (AIS, ECE, SAE, FMVSS).\\\\n- Develop and execute DVP&R for environmental, optical, electrical, EMC/EMI, durability, corrosion, vibration, sealing, thermal and vehicle\\\\u2011level integration (CAN/LIN comms, diagnostics).\\\\n- Ensure global regulatory compliance (e.g., UNECE, AIS/BIS, SAE/ISO etc.)\\\\nQuality & Risk\\\\n- Drive APQP/PPAP, DFMEA/PFMEA, Control Plan, and 8D resolution; ensure lessons learned reuse and robust problem prevention.\\\\n- Champion traceability for critical components (LED binning, lens material lots, PCB revisions).\\\\nSupplier & Sourcing Leadership\\\\n- Manage supplier partnerships to achieve cost, quality, and delivery targets.\\\\n- Manage Tier\\\\u20111/Tier\\\\u20112 suppliers; negotiate technology, cost, and timing; define SOW and acceptance criteria.\\\\n- Conduct design reviews, audits, and process capability checks; support tooling and gauge development.\\\\nProgram & Cross\\\\u2011Functional Leadership\\\\n- Own timelines, budgets, and BOM for lighting commodities; manage EBOM/MBOM alignment.\\\\n- Collaborate with Manufacturing Engineering for line readiness, PFMEA, jigs/fixtures, EOL testing.\\\\n- Interface with After\\\\u2011Sales for service parts strategy, diagnostics, and repairability.\\\\nInnovation & IP\\\\n- Drive innovation in lighting technologies (LED, Light Projection, OLED, laser, adaptive Lighting, matrix Lighting, smart lighting).\\\\n- Incubate new features (Welcome/Goodbye animations, ADB/Matrix, logo projection, adaptive signatures, OTA\\\\u2011capable diagnostics) and file patents/IP where applicable.\\\\nSustainability & Compliance\\\\n- Embed recyclability and drive weight and cost reduction.\\\", \\\"Experience\\\": \\\"Total Experience: 10\\\\u201312 years (minimum 7 years in automotive lighting systems; OEM/Tier\\\\u20111 mix preferred).\\\\nProven track record in lighting systems development (headlamps, tail lamps, DRLs, interior lighting, adaptive lighting)\\\\nExperience in OEM product lifecycle management (PLM) from concept to launch - \\\\u22652 full vehicle programs through SOP.\\\\nHands\\\\u2011on with mechanical/optical/thermal/electrical design and vehicle integration.\\\\nProven track record with APQP/PPAP, DFMEA/PFMEA, DVP&R, and homologation.\\\\nVendor and supplier management experience, especially with Tier-1 lighting suppliers in India and global regions; tooling, injection moulding, and aluminium die casting for heat sinks.\\\\nExposure to domestic and global automotive standards (AIS, ECE, ISO, SAE, FMVSS).\\\\nAdvantage: Exposure to adaptive/matrix headlamps, LIN/CAN diagnostics, ISO 26262 and ASPICE for electronics/software components\\\", \\\"Industry Preferred\\\": \\\"Any other OEMs or Tier-1s like Lumax, Uno Minda, Valeo, Varroc, Marelli, Hella etc\\\", \\\"Qualifications\\\": \\\"Bachelor\\\\u2019s degree in Mechanical, Electrical, Electronics, Mechatronics or Automotive Engineering.\\\\nMaster\\\\u2019s degree in Engineering Management, Product Design, or Business Administration preferred.\\\\nSpecialized certifications in automotive lighting technologies, optics, or electronics are an advantage.\\\", \\\"General Requirements\\\": \\\"\'Lighting Engineering\\\\n- Deep knowledge and expertise in lighting technologies: Halogen, LED, MFR, Light Guides, Light Blades, Projection systems, adaptive, matrix systems.\\\\n- Lighting Electronics: deep knowledge of driver circuits, control modules, sensors, microcontrollers, LED selection/binning, thermal derating, PCBs, ESD/EMI design and integration with vehicle electrical architecture (CAN/LIN/Ethernet communication, diagnostics, software calibration & EOL test strategies.).\\\\n- Knowledge of optical design - \\\\u00a0reflector/projector, light guides, micro\\\\u2011optics, photometry (luminous flux, intensity, distributions), glare control\\\\n- Knowledge of Thermal & Mechanical design : CFD for heat dissipation, heat sink design, material selection, sealing/venting, vibration and durability.\\\\n- Knowledge of Standards: AIS/BIS, UNECE & FMVSS/SAE standards.\\\\nMethods & Tools\\\\n- Familiarity in CAD tools: CATIA V5/V6; GD&T, tolerance analysis.\\\\n- Familiarity in CAE analysis tools: thermal simulation, basic optical simulation exposure (Ansys Speos, Lucid).\\\\n- Quality: DFMEA/PFMEA, PPAP, Control Plans.\\\\n- Program tools: PLM (Teamcenter, 3DX), requirements management, Jira/MS Project, dashboards.\\\\nManufacturing & Industrialization\\\\n- Injection moulding (optical\\\\u2011grade lenses, surface quality/flow), coating & metallization (aluminium vacuum metallization).\\\\n- Welding techniques - Laser welding, ultrasonic welding & Hotplate Welding. Sealing/venting processes, potting, conformal coating, PCB assembly.\\\\n- Assembly line design, EOL optical & leakage tests, poka\\\\u2011yoke.\\\", \\\"Our commitment to Diversity, Equity, and Inclusion\\\": \\\"Job Segment:\\\\nElectronics Engineer, Thermal Engineering, Engineering Manager, Welding, Engineering, Automotive, Manufacturing\\\\nApply Now\\\\nStart apply with LinkedIn\\\\nStart\\\\nPlease wait...\\\"}\"',NULL,NULL,'OWNED',NULL,NULL,'2026-10-17 12:30:19.260257','{\"city\": \"Chennai\", \"title\": \"Senior Lead Engineer- VES\", \"location\": \"Chennai, Chennai-MRV-AD, IN\", \"source_url\": \"https://jobs.mahindracareers.com/search/?q=&startrow=500\", \"ats_platform\": \"SuccessFactors\", \"evidence_text\": \"{\\\"title\\\": \\\"Senior Lead Engineer- VES\\\", \\\"id\\\": \\\"1432843300\\\", \\\"url\\\": \\\"/job/Chennai-Senior-Lead-Engineer-VES-Chen/1432843300/\\\", \\\"location\\\": \\\"Chennai, Chennai-MRV-AD, IN\\\"}\", \"detail_fetched\": false, \"application_url\": \"https://jobs.mahindracareers.com/job/Chennai-Senior-Lead-Engineer-VES-Chen/1432843300/\", \"external_job_id\": \"1432843300\", \"detail_fetch_status\": \"NOT_FETCHED\"}','ats_direct_successfactors','DIRECT',NULL,'{\"raw_title\": \"raw_metadata.title\", \"raw_location\": \"location\"}',NULL,'{}',NULL,NULL,NULL,'Chennai, Chennai-MRV-AD, IN','Senior Lead Engineer- VES'),(5912,'JOB_COMP_TOP200_011_2d3e56d7f3bd','Sr. Engineer-VIPTIS',NULL,NULL,'Chennai, Chennai-MRV-AD, IN','Chennai-MRV-AD','India',NULL,NULL,NULL,NULL,NULL,NULL,'Responsibilities & Key Deliverables\n1. Packaging and integrating vehicle systems into a vehicle\n2. Monitor Virtual vehicle layout and finalize PandH (Proportions and Hard points) and Vehicle Architecture\n3. Manage Variants andmeet project specific communisation and standardization targets\n4. Conceptualize and detailed design VI systems meeting cost weight and functional targets\n5. Exposure to Team centre Â Enterprise, TC-engineering and TC-project (Product Lifecycle Management tools)\n6. Ensure CAD Vehicle Layout to facilitate design engg for modification insertion / introduction of the new parts in the vehicle by collecting all the CAD models together and locating at vehicle location\n7. Manage Vehicle level Engineering Bill of Material to support Vehicle Build during Product Development\n8. Ensure compliance of customer requirements arising out of QFD to deliver the vehicle as per the customer requirements by continuously monitoring design of various systems\nExperience\n5 to 10 Years\nIndustry Preferred\nAuto and Auto allied Industries\nQualifications\nBE/B.Tech\nGeneral Requirements\nOur commitment to Diversity, Equity, and Inclusion\nAt Mahindra and Mahindra Limited, we believe that diversity drives innovation, and inclusion is at the heart of everything we do. We are committed to cultivating a workplace where every individual feels valued, respected, and empowered to thrive.\nWe are proud to be an Equal Opportunity Employer. All qualified applicants will be considered for employment without regard to age, caste, race, religion, color, ethnic origin, gender identity, nationality, physical or mental disability, medical condition, sexual orientation, educational background, marital or domestic partnership status, pregnancy or childbirth, veteran status, citizenship status, ancestry, financial status, or any other personal characteristic protected by applicable law.\nWe actively encourage candidates from all backgrounds to apply and bring their unique perspectives to our teams. We are committed to ensuring an accessible and inclusive experience for all applicants.\nTogether, we rise by embracing differences and building a future that reflects the communities we serve.',NULL,NULL,'https://jobs.mahindracareers.com/job/Chennai-Sr_-Engineer-VIPTIS-Chen/1432823500','https://jobs.mahindracareers.com/search/?q=&startrow=400','2026-10-13T12:16:41.045568+00:00','EXPIRED',0.98,'PUBLISHED',NULL,'Crawler (ATS_API_SUCCESSFACTORS)','83340fe68db978928c1792c5dfee9e44069128ca0a716894d0e71c91ba00a4c3','COMP_TOP200_011','https://jobs.mahindracareers.com/job/Chennai-Sr_-Engineer-VIPTIS-Chen/1432823500','d745b4b7d7619bb600dcbb9abbe6fe63',NULL,'{\"title\": \"Sr. Engineer-VIPTIS\", \"location\": \"Chennai, Chennai-MRV-AD, IN\", \"date\": null, \"function\": null, \"pay_band\": null, \"sections_extracted\": [\"Experience\", \"Industry Preferred\", \"Our commitment to Diversity, Equity, and Inclusion\"]}','ATS_API_SUCCESSFACTORS','2026-10-13 05:21:34.459231',NULL,'2026-10-13 05:21:34.456108',NULL,NULL,'2026-10-13 05:21:34.456108',NULL,'<!DOCTYPE html>\n<html class=\"html5\" xml:lang=\"en-GB\" lang=\"en-GB\" xmlns=\"http://www.w3.org/1999/xhtml\">\n\n        <head>\n            <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge,chrome=1\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html;charset=UTF-8\" />\n            <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n                        <link type=\"text/css\" class=\"keepscript\" rel=\"stylesheet\" href=\"https://jobs.mahindracareers.