m/en/144330138','2026-10-19T12:28:19.716481+00:00','ACTIVE',0,'LINK_FALLBACK',NULL,NULL,'54919e43e7e3dcfd73b881222823b6868d4d285aaddf256b15b9177860d48e07','COMP_TOP200_042','https://careers.motherson.com/en/144330138','f1fc56790a9fd60fb2dd44675127b62d',NULL,'Discover your team',NULL,'2026-10-19 12:28:19.716481',NULL,'2026-10-19 12:28:19.716481',NULL,NULL,'2026-10-19 12:28:19.716481',NULL,NULL,NULL,NULL,'SOURCE_CONFIRMED',NULL,NULL,NULL,NULL,'Mumbai / New Delhi / Chennai',0,NULL,'144330138',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,'OWNED',NULL,NULL,'2026-10-19 12:28:19.716481','{\"id\": \"144330138\", \"title\": \"Discover your team\", \"display\": \"With jobs\", \"__typename\": \"FunctionalAreaOverviewRecord\", \"functionalAreas\": [{\"id\": \"100226078\", \"name\": \"Human Resources\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 20}, {\"id\": \"100226077\", \"name\": \"Information Technologies\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 8}, {\"id\": \"100226070\", \"name\": \"Manufacturing/Operations\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 74}, {\"id\": \"141553514\", \"name\": \"Apprentices/Trainees\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 0}, {\"id\": \"141553543\", \"name\": \"Environment Health and Safety\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 41}, {\"id\": \"141553527\", \"name\": \"Engineering\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 58}, {\"id\": \"100226048\", \"name\": \"Finance and Control\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 14}, {\"id\": \"100226076\", \"name\": \"General Administration\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 43}, {\"id\": \"100226075\", \"name\": \"Logistics\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 48}, {\"id\": \"100226074\", \"name\": \"Purchasing\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 14}, {\"id\": \"141553534\", \"name\": \"Quality\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 26}, {\"id\": \"141553529\", \"name\": \"R&D\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 2}, {\"id\": \"141553519\", \"name\": \"Sales/Marketing\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 11}], \"functionalAreaGroups\": [{\"id\": \"141553527\", \"name\": \"Engineering\", \"labelText\": \"Engineering\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 58, \"labelColor\": {\"hex\": \"#41B7CA\"}, \"description\": \"<p>Our engineers work directly with our customers throughout the entire process right from the drawing board to production. A strong technical background, particularly in the automotive industry, electronics, electro-mechanics, power distribution, and/or wire harness assembly, is advantageous. We value creativity and an inventive approach as it allows our engineers to envision new and better solutions that will help both Motherson and our customers meet future challenges. Strong communication and interpersonal skills are also essential.</p>\", \"functionalAreas\": [{\"id\": \"111936855\", \"name\": \"Engineering & Technical\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 32, \"careerLevels\": []}, {\"id\": \"91708432\", \"name\": \"Industrial Engineering\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 1, \"careerLevels\": []}, {\"id\": \"111936787\", \"name\": \"Manufacturing Engineering\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 17, \"careerLevels\": []}, {\"id\": \"111936789\", \"name\": \"Project Management\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 1, \"careerLevels\": []}, {\"id\": \"91708381\", \"name\": \"Product Engineering\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 7, \"careerLevels\": []}]}, {\"id\": \"141553543\", \"name\": \"Environment Health and Safety\", \"labelText\": \"Environment Health and Safety\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 41, \"labelColor\": {\"hex\": \"#8250C4\"}, \"description\": \"<p>Our Environmental Health and Safety team has a zero-tolerance policy for potentially hazardous situations or conditions in our facilities. They understand both internal safety protocols and all external local and national safety laws that apply to their facility. Candidates should have an uncompromising commitment to both anticipating and identifying unsafe conditions.</p>\", \"functionalAreas\": [{\"id\": \"111936858\", \"name\": \"Other Disciplines\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 1, \"careerLevels\": []}, {\"id\": \"91708434\", \"name\": \"Fire Brigade\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 0, \"careerLevels\": []}, {\"id\": \"111936851\", \"name\": \"Health, Medical & Social\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 4, \"careerLevels\": []}, {\"id\": \"91708429\", \"name\": \"Others\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 36, \"careerLevels\": []}]}, {\"id\": \"100226048\", \"name\": \"Finance and Control\", \"labelText\": \"Finance and Control\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 14, \"labelColor\": {\"hex\": \"#48B500\"}, \"description\": \"<p><span>An opening in the Finance and Control function encompasses a variety of accounting, financial control, and treasury management responsibilities. Candidates must enjoy working with numbers and delivering timely analyses and information to various levels of management to aid in both local and global decision-making. In addition to preparing regular scheduled reports, this job also requires ad hoc reporting. Good communication and cooperation skills are essential as this position requires collaboration with both internal and external stakeholders.</span></p>\", \"functionalAreas\": [{\"id\": \"91706833\", \"name\": \"Controlling & Finance\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 6, \"careerLevels\": []}, {\"id\": \"111936860\", \"name\": \"Finance, Accounting & Controlling\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 8, \"careerLevels\": []}]}, {\"id\": \"100226076\", \"name\": \"General Administration\", \"labelText\": \"General Administration\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 43, \"labelColor\": {\"hex\": \"#FF0000\"}, \"description\": \"<p>General administration tasks vary depending on location and can include document management, travel arrangements, office management, and senior-level executive assistance. This position necessitates strong interpersonal skills as well as the ability to communicate effectively and efficiently. Our administrators are committed to completing tasks on time and in accordance with Group standards. Candidates with qualities such as dependability, a strong work ethic, accuracy, and attention to detail are ideal.</p>\", \"functionalAreas\": [{\"id\": \"111936821\", \"name\": \"Management & Corporate Development\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 0, \"careerLevels\": []}, {\"id\": \"91708429\", \"name\": \"Others\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 36, \"careerLevels\": []}, {\"id\": \"111936858\", \"name\": \"Other Disciplines\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 1, \"careerLevels\": []}, {\"id\": \"91706802\", \"name\": \"Administration\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 6, \"careerLevels\": []}]}, {\"id\": \"100226078\", \"name\": \"Human Resources\", \"labelText\": \"Human Resources\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 20, \"labelColor\": {\"hex\": \"#EAB600\"}, \"description\": \"<p><span>The HR community promotes the group values and fosters a healthy work environment. The profile includes performance management, employee training and development, facilitating internal communication, and talent acquisition and retention. The HR team is also responsible for the health, safety and well-being of employees.</span></p>\", \"functionalAreas\": [{\"id\": \"91706834\", \"name\": \"Human Resources\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 20, \"careerLevels\": []}]}, {\"id\": \"100226077\", \"name\": \"Information Technologies\", \"labelText\": \"IT\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 8, \"labelColor\": {\"hex\": \"#7000FF\"}, \"description\": \"<p>The IT department has a variety of positions available that require a current knowledge of the latest advances in hardware, software, data, and cybersecurity management, among other competencies. Strong communication skills are required for providing efficient internal and external technical support, as well as communicating and collaborating with customers about their hardware and software requirements. We value a hands-on attitude, a strong work ethic, attention to detail, as well as problem-solving abilities.</p>\", \"functionalAreas\": [{\"id\": \"91708431\", \"name\": \"IT & Software Development\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 8, \"careerLevels\": []}]}, {\"id\": \"100226075\", \"name\": \"Logistics\", \"labelText\": \"Logistics\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 48, \"labelColor\": {\"hex\": \"#66DADA\"}, \"description\": \"<p>The Logistics Department ensures both timely dispatch and delivery to customers. Team members are responsible for maintaining inventory levels, optimising lot sizes and freight costs, and scheduling deliveries to meet the needs of our customers.<br>Knowledge of ERP/MRP and EDI as well as familiarity with the industrial environment are advantageous.<br>Candidates should be good at communication, organisation and planning. The ability to work under pressure is advantageous as the Logistics Department is frequently required to find quick solutions to problems that arise in the global supply chain.</p>\", \"functionalAreas\": [{\"id\": \"91706843\", \"name\": \"Logistics\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 38, \"careerLevels\": []}, {\"id\": \"111936829\", \"name\": \"Process Planning & QA\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 3, \"careerLevels\": []}, {\"id\": \"111936800\", \"name\": \"Purchasing, Materials Management & Logistics\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 7, \"careerLevels\": []}]}, {\"id\": \"100226070\", \"name\": \"Manufacturing/Operations\", \"labelText\": \"Manufacturing\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 74, \"labelColor\": {\"hex\": \"#005AE0\"}, \"description\": \"<p>Working on the shop floor requires dexterity, physical fitness, and a knack for working with machinery. We are looking for people to work on the preparation and assembly of wire harnesses and cables, as well as related electrical and mechanical parts. We also have openings for various support positions, such as tooling and equipment maintenance and production team leaders.</p>\", \"functionalAreas\": [{\"id\": \"111936805\", \"name\": \"Production & Manufacturing\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 8, \"careerLevels\": []}, {\"id\": \"91708392\", \"name\": \"Production\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 58, \"careerLevels\": []}, {\"id\": \"91706850\", \"name\": \"Production Excellence\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 0, \"careerLevels\": []}, {\"id\": \"91708430\", \"name\": \"Facility Management / Maintenance\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 7, \"careerLevels\": []}, {\"id\": \"111936859\", \"name\": \"Product Management\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 1, \"careerLevels\": []}]}, {\"id\": \"100226074\", \"name\": \"Purchasing\", \"labelText\": \"Purchasing\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 14, \"labelColor\": {\"hex\": \"#F394E4\"}, \"description\": \"<p>The Purchasing Department\'s responsibilities include coordinating the flow of orders to ensure on-time deliveries, vendor management, and contract negotiations in direct and indirect sourcing. Members of the Purchasing Department maintain operational relationships with suppliers and optimise purchases and contracts which requires cooperation and coordination across various divisions of the group.<br>Attributes that are needed are a &nbsp;positive attitude, excellent communication skills, and the ability to positively influence others.</p>\", \"functionalAreas\": [{\"id\": \"91708399\", \"name\": \"Purchasing\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 7, \"careerLevels\": []}, {\"id\": \"111936800\", \"name\": \"Purchasing, Materials Management & Logistics\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 7, \"careerLevels\": []}]}, {\"id\": \"141553534\", \"name\": \"Quality\", \"labelText\": \"Quality\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 26, \"labelColor\": {\"hex\": \"#0A8B1A\"}, \"description\": \"<p>The Quality Department supports the implementation and continuous improvement of quality management systems, conducts process and product audits. Team members respond to supplier and customer concerns while actively monitoring work on the shop floor to identify potential and actual quality issues. Candidates should have knowledge of quality-assessment tools and have a systematic and analytical approach to problem-solving. Strong interpersonal and communication skills are also required.</p>\", \"functionalAreas\": [{\"id\": \"91708422\", \"name\": \"Quality Management\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 23, \"careerLevels\": []}, {\"id\": \"111936829\", \"name\": \"Process Planning & QA\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 3, \"careerLevels\": []}]}, {\"id\": \"141553529\", \"name\": \"R&D\", \"labelText\": \"R&D\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 2, \"labelColor\": {\"hex\": \"#BE5E3E\"}, \"description\": \"<p>The Research and Development team is made up of people who want to delve deep into the details of design and production. We are looking for curious individuals who ask \\\"Why?\\\" as well as \\\"Why not?\\\" A technical background is advantageous, as are qualities such as natural curiosity, the ability to collaborate effectively with others, a passion for innovation, and a creative, inventive approach to the job. \\\"Imaginators\\\" are welcome!</p>\", \"functionalAreas\": [{\"id\": \"91706807\", \"name\": \"Research & Development\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 2, \"careerLevels\": []}, {\"id\": \"111936799\", \"name\": \"Teaching, R&D\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 0, \"careerLevels\": []}, {\"id\": \"111936790\", \"name\": \"Advanced Development\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 0, \"careerLevels\": []}]}, {\"id\": \"141553519\", \"name\": \"Sales/Marketing\", \"labelText\": \"Sales/Marketing\", \"__typename\": \"FunctionalAreaGroupRecord\", \"jobsAmount\": 11, \"labelColor\": {\"hex\": \"#FFD942\"}, \"description\": \"<p>The Sales and Marketing team is responsible for both maintaining our existing customer base and identifying new business opportunities. Tasks include conducting market and customer analyses, &nbsp;handling customer and contract negotiations and solving operational issues in collaboration with customers, product managers, and our engineering team. Candidates applying for this position must have a customer-oriented mindset, market knowledge, the ability to transform analysis into thoughtful advice and good decisions, and strong communication skills.&nbsp;</p>\", \"functionalAreas\": [{\"id\": \"91708423\", \"name\": \"Sales\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 3, \"careerLevels\": []}, {\"id\": \"111936820\", \"name\": \"Sales & Commerce\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 4, \"careerLevels\": []}, {\"id\": \"111936785\", \"name\": \"Graphic Design & Architecture\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 0, \"careerLevels\": []}, {\"id\": \"L67ih7jKQKuqUniYW5en4Q\", \"name\": \"Customer Service\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 1, \"careerLevels\": []}, {\"id\": \"111936865\", \"name\": \"Marketing & Advertising\", \"__typename\": \"FunctionalAreaRecord\", \"jobsAmount\": 3, \"careerLevels\": []}]}]}','http_status_404','LISTING_FALLBACK',NULL,'{\"raw_title\": \"raw_metadata.title\", \"raw_location\": \"location\", \"raw_department\": \"department\", \"raw_employment_type\": \"employment_type\"}',NULL,'{}',NULL,'Corporate','Full-time','India','Discover your team'),(12269,'JOB_COMP_TOP200_042_6c536ff5ba29','Gobally present, regionally supported','Corporate',NULL,'India',NULL,NULL,'On-site','Full-time',NULL,NULL,NULL,NULL,'Gobally present, regionally supported',NULL,NULL,'https://careers.motherson.com/en/locations','https://careers.motherson.com/en/locations','2026-10-19T12:28:19.716481+00:00','ACTIVE',0,'LINK_OK','2026-10-19 12:28:19.716481',NULL,'6c536ff5ba29ba0c98edc9eb13d01be50d8deda8b1943eee97f501df93e0918c','COMP_TOP200_042','https://careers.motherson.com/en/locations','17de6be2dd7ac3c3fc13ad672ca87fe8',NULL,'Gobally present, regionally supported',NULL,'2026-10-19 12:28:19.716481',NULL,'2026-10-19 12:28:19.716481',NULL,NULL,'2026-10-19 12:28:19.716481',NULL,NULL,NULL,NULL,'SOURCE_CONFIRMED',NULL,NULL,NULL,NULL,'Mumbai / New Delhi / Chennai',0,NULL,'locations',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NOT_FETCHED',NULL,NULL,NULL,NULL,NULL,NULL,'OWNED',NULL,NULL,'2026-10-19 12:28:19.716481','{\"seo\": null, \"slug\": \"locations\", \"title\": \"Gobally present, regionally supported\"}','verified